# REASONING ENGINE  -- Multi-step thinking to answer questions
# ============================================================================

class ReasoningEngine:
    """
    Aurora's ability to THINK through a question rather than just retrieve
    a template.  Chains: working memory â†' OETS knowledge â†' search evidence
    to form a direct, meaningful answer.
    """

    _PROPERTY_WORDS = {
        'color', 'colour', 'size', 'weight', 'shape', 'smell', 'taste',
        'sound', 'texture', 'temperature', 'height', 'length', 'width',
        'speed', 'age', 'type', 'kind', 'purpose', 'function', 'cause',
        'effect', 'meaning', 'definition', 'example', 'location', 'origin',
    }

    _COLOR_WORDS = {
        'red', 'blue', 'green', 'yellow', 'orange', 'purple', 'pink',
        'black', 'white', 'gray', 'grey', 'brown', 'violet', 'cyan',
        'magenta', 'indigo', 'gold', 'silver', 'maroon', 'olive', 'teal',
    }

    _ABSTRACT_BREAK_MARKERS = (
        'what breaks', 'what would break', 'what falls apart', 'what fails',
        'what degrades', 'what fragments',
    )
    _NEXT_STEP_MARKERS = (
        'what happens next', 'what happens then', 'what follows', 'then what',
        'what should happen next',
    )
    _CONNECTIVITY_MARKERS = (
        'stay connected', 'keep connected', 'stay anchored', 'keep anchored',
        'stay tied', 'keep tied',
    )
    _DETACH_MARKERS = (
        'detached from', 'disconnected from', 'separated from', 'cut off from',
        'without grounding', 'loses grounding', 'lost grounding',
    )

    def reason(self, user_text: str, understood: dict,
               working_memory, oets, evidence: list = None,
               systems: Optional[Dict[str, Any]] = None) -> str:
        """
        Try to answer user_text by stepping through available knowledge.
        Chain: personal perspective -> working_memory facts -> property reasoning
               -> OETS definitions -> evidence extraction.
        Returns answer string or "" if reasoning fails.
        """
        import re
        topic = understood.get('topic', '')
        topic_words = understood.get('topic_words', [])
        query_type = understood.get('query_type', '')
        answer = ""

        # Skip stored-meaning lookup when asking for Aurora's personal view
        # or addressing her internal state ("cost you", "your mind", etc.)
        _personal_pov_early = any(p in (user_text or '').lower() for p in (
            'to you', 'for you', 'in your view', 'in your opinion',
            'from your perspective', 'what do you think', 'how do you think', 'what do you feel',
            'how do you see', 'how do you feel about', 'your take', 'your mind', 'your sense',
            'cost you', 'you feel', 'you think', 'you exist', 'you experience',
        )) or bool((understood or {}).get("_is_personal_perspective"))

        # Only use OETS/evidence for actual knowledge questions  -- not conversational text
        _is_knowledge_query = (
            user_text.strip().endswith('?') or
            query_type in ('definition', 'factual_entity', 'factual_general',
                           'weather_location', 'how_to', 'hypothetical') or
            bool((understood or {}).get('is_hypothetical')) or
            any(user_text.lower().startswith(w) for w in (
                'what', 'how', 'why', 'where', 'who', 'when', 'which',
                'can', 'could', 'would', 'is ', 'are ', 'do ', 'does ',
                'define', 'explain', 'tell me', 'look up', 'if ', 'suppose ',
            ))
        )

        # Step 1: Deep Manifold Resolution (Native Language Reasoning)
        if _personal_pov_early or not _is_knowledge_query:
            answer = self._reason_personal_perspective(user_text, understood, systems)
            if answer: return answer

        if not _is_knowledge_query: return ""

        # Step 2: Knowledge Extraction
        if working_memory and hasattr(working_memory, "answer_from_meanings"):
            try:
                answer = working_memory.answer_from_meanings(user_text, understood, systems=systems)
                if not answer:
                    answer = working_memory.answer_from_claims(user_text, understood, systems=systems)
                if not answer:
                    answer = self._reason_from_active_claim(user_text, understood, working_memory)
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:646",
                    exc=_aurora_boundary_exc,
                    context={"function": "reason", "handler_line": 646, "source_file": "aurora.py"},
                )
                pass
            if answer:
                self._update_memory_from_reasoning(answer, topic, systems)
                return answer

        if working_memory and topic_words:
            for tw in topic_words:
                facts = working_memory.get_stated_fact(tw)
                if facts:
                    color = facts.get('color')
                    desc = facts.get('description')
                    if color and any(w in user_text.lower() for w in ('color', 'colour')):
                        answer = f"fact; {tw}; color; {color}"
                        break
                    if desc and not (hasattr(working_memory, "should_suppress_surface_meta_answer") and
                                   working_memory.should_suppress_surface_meta_answer(user_text, understood=understood, term=tw)):
                        answer = f"fact; {tw}; description; {desc}"
                        break
            if answer:
                self._update_memory_from_reasoning(answer, topic or topic_words[0], systems)
                return answer

        # Step 3: Property Reasoning
        if len(topic_words) >= 2 and topic_words[0] in self._PROPERTY_WORDS:
            property_word = topic_words[0]
            subject_word = topic_words[1]
            if working_memory:
                val = working_memory.get_stated_fact(subject_word, property_word)
                if val: answer = f"property; {subject_word}; {property_word}; {val}"
            if not answer and oets:
                answer = self._oets_property_lookup(subject_word, property_word, oets)
            if not answer and evidence:
                answer = self._evidence_property_lookup(property_word, subject_word, evidence)
            if answer:
                self._update_memory_from_reasoning(answer, subject_word, systems)
                return answer

        # Step 4: OETS & Ability-Guided Reasoning
        if oets and topic and query_type == 'definition' and not _personal_pov_early:
            node = oets.web.get_node(topic)
            if node and node.definitions:
                best = node.definitions[0].get('text', '')
                # Crest-compression placeholder-leak repair (Build 598): this path
                # read node.definitions[0] directly and never called
                # _meaning_text_is_grounded(), so an internal bookkeeping label
                # (e.g. "internal:topic") could pass its own narrower inline check
                # and be spoken verbatim -- the same invariant the shared guard
                # protects elsewhere, unified here rather than re-implemented.
                if (
                    'may refer to' not in best.lower() and not best.strip().endswith(':')
                    and len(best) > 15 and _meaning_text_is_grounded(best, term=topic)
                ):
                    answer = f"understanding; {topic}; {best}"
                    related = [r.target_word if r.source_word == topic else r.source_word for r in list(node.relations.values())[:3]]
                    if related: answer += f"; connected to; {'; '.join(related[:3])}"
                    self._update_memory_from_reasoning(answer, topic, systems)
                    return answer

        # Ability-Guided (Connect/Bridge/Resolve)
        _ability_effects = list((understood or {}).get("_active_ability_effects", []) or [])
        if _ability_effects and systems and working_memory:
            answer = _ability_guided_context_answer(systems, user_text, understood=understood, ability_effects=_ability_effects)
            if answer:
                self._update_memory_from_reasoning(answer, topic, systems)
                return answer

        # Step 5: Evidence & Manifold Fallback
        if evidence:
            answer = _extract_factual_answer(user_text, evidence)
            if answer:
                self._update_memory_from_reasoning(answer, topic, systems)
                return answer

        if _personal_pov_early:
            answer = self._reason_personal_perspective(user_text, understood, systems)
            if answer:
                self._update_memory_from_reasoning(answer, topic, systems)
                return answer

        return ""

        if working_memory and hasattr(working_memory, "answer_from_meanings"):
            try:
                meaning_answer = working_memory.answer_from_meanings(user_text, understood, systems=systems)
                if meaning_answer:
                    return meaning_answer
                claim_answer = working_memory.answer_from_claims(user_text, understood, systems=systems)
                if claim_answer:
                    return claim_answer
                causal_claim_answer = self._reason_from_active_claim(
                    user_text,
                    understood,
                    working_memory,
                )
                if causal_claim_answer:
                    return causal_claim_answer
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:733",
                    exc=_aurora_boundary_exc,
                    context={"function": "reason", "handler_line": 733, "source_file": "aurora.py"},
                )
                pass

        if working_memory and topic_words:
            for tw in topic_words:
                facts = working_memory.get_stated_fact(tw)
                if facts:
                    color = facts.get('color')
                    desc = facts.get('description')
                    if color and any(w in user_text.lower() for w in ('color', 'colour')):
                        return f"fact; {tw}; color; {color}"
                    if desc and not (
                        working_memory is not None and
                        hasattr(working_memory, "should_suppress_surface_meta_answer") and
                        working_memory.should_suppress_surface_meta_answer(
                            user_text,
                            understood=understood,
                            term=tw,
                        )
                    ):
                        return f"fact; {tw}; description; {desc}"

        # Step 2: Detect property questions  -- "what COLOR is SUBJECT?"
        #  topic_words[0] = property, topic_words[1] = subject
        if len(topic_words) >= 2 and topic_words[0] in self._PROPERTY_WORDS:
            property_word = topic_words[0]
            subject_word = topic_words[1]

            # Check working memory for the specific property
            if working_memory:
                val = working_memory.get_stated_fact(subject_word, property_word)
                if val:
                    return f"The {property_word} of {subject_word} is {val}."

            # Check OETS definition for the subject
            if oets:
                answer = self._oets_property_lookup(subject_word, property_word, oets)
                if answer:
                    return answer

            # Check evidence for property+subject co-occurrence
            if evidence:
                answer = self._evidence_property_lookup(property_word, subject_word, evidence)
                if answer:
                    return answer

        # Step 3: OETS definition answer  -- only for genuine definition queries
        # Skip if the user is asking for Aurora's personal perspective ("to you", etc.)
        _personal_pov = any(p in (user_text or '').lower() for p in (
            'to you', 'for you', 'in your view', 'in your opinion',
            'from your perspective', 'what do you think', 'how do you think', 'what do you feel',
            'how do you see', 'how do you feel about', 'your take',
        )) or bool((understood or {}).get("_is_personal_perspective"))
        if oets and topic and query_type == 'definition' and not _personal_pov:
            node = oets.web.get_node(topic)
            if node and node.definitions:
                best = node.definitions[0].get('text', '')
                # Skip disambiguation pages and empty/colon-terminated entries
                _best_low_re = best.lower()
                # Crest-compression placeholder-leak repair (Build 598): also
                # require _meaning_text_is_grounded() -- see the matching
                # comment at the Step 4 occurrence of this same pattern above.
                if (
                    'may refer to' not in _best_low_re and not best.strip().endswith(':')
                    and len(best) > 15 and _meaning_text_is_grounded(best, term=topic)
                ):
                    related = []
                    for rel in list(node.relations.values())[:3]:
                        other = (rel.target_word if rel.source_word == topic
                                 else rel.source_word)
                        if other and other != topic:
                            related.append(other)
                    # Return as fragments so SIC authors a generative sentence
                    answer = f"understanding; {topic}; {best}"
                    if related:
                        answer += f"; connected to; {'; '.join(related[:3])}"
                    return answer

        # Step 3.5: Ability-guided OETS strategies
        # Active abilities pass their effect_tags through pipeline_state -> understood.
        # Each strategy runs ONLY if relevant tags are present and no answer found yet.
        _ability_effects = list((understood or {}).get("_active_ability_effects", []) or [])
        if _ability_effects and systems and working_memory:
            _runtime_flags = dict(
                ((systems or {}).get("_last_pipeline_state") or {}).get("ability_runtime_flags", {}) or {}
            )
            _force_carryover = any(
                marker in str(user_text or '').lower() for marker in (
                    'remember',
                    'recall',
                    'what did i say',
                    'what was my',
                    'what is my',
                    "what's my",
                )
            )
            if _runtime_flags.get("force_continuity_recall") and (
                bool((understood or {}).get("is_callback")) or
                bool((understood or {}).get("is_clarification"))
            ):
                _force_carryover = True
            carryover_answer = _ability_guided_context_answer(
                systems,
                user_text,
                understood=understood,
                ability_effects=_ability_effects,
                force=_force_carryover,
            )
            if carryover_answer:
                return carryover_answer

        # connect/bridge: surface OETS relations between topic concepts
        if oets and topic and any(t in _ability_effects for t in ("connect", "bridge", "connect_bridge")):
            try:
                _cn = oets.web.get_node(topic) if hasattr(oets, "web") else None
                if _cn and hasattr(_cn, "relations"):
                    _rels = []
                    for _rel in list(_cn.relations.values())[:6]:
                        _other = _rel.target_word if _rel.source_word == topic else _rel.source_word
                        _rtype = str(getattr(_rel, "relation_type", "") or "")
                        if _other and _other != topic:
                            _rels.append(f"{_other}" + (f" ({_rtype})" if _rtype else ""))
                    if _rels:
                        return f"{topic.capitalize()} connects to: {', '.join(_rels[:4])}."
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:851",
                    exc=_aurora_boundary_exc,
                    context={"function": "reason", "handler_line": 851, "source_file": "aurora.py"},
                )
                pass

        # resolve/merge_conflict: surface contradictions in OETS definitions
        if oets and topic and any(t in _ability_effects for t in ("resolve", "merge_conflict")):
            try:
                _rn = oets.web.get_node(topic) if hasattr(oets, "web") else None
                if _rn and hasattr(_rn, "definitions") and len(_rn.definitions) > 1:
                    _d0 = str((_rn.definitions[0] or {}).get("text", "") or "")
                    _d1 = str((_rn.definitions[1] or {}).get("text", "") or "")
                    if _d0 and _d1 and _d0[:60] != _d1[:60]:
                        return (
                            f"{topic.capitalize()} has competing definitions: "
                            f"\"{_d0[:80]}\" vs \"{_d1[:80]}\". "
                            f"I hold both without forcing a resolution."
                        )
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:867",
                    exc=_aurora_boundary_exc,
                    context={"function": "reason", "handler_line": 867, "source_file": "aurora.py"},
                )
                pass

        # reclassify/reindex: consider alternative categories for the concept
        if oets and topic and any(t in _ability_effects for t in ("reclassify", "reindex")):
            try:
                _rcn = oets.web.get_node(topic) if hasattr(oets, "web") else None
                if _rcn and hasattr(_rcn, "categories") and _rcn.categories:
                    _cats = [str(c) for c in list(_rcn.categories)[:3] if c]
                    if _cats:
                        return f"{topic.capitalize()} can be understood as: {', '.join(_cats)}."
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:878",
                    exc=_aurora_boundary_exc,
                    context={"function": "reason", "handler_line": 878, "source_file": "aurora.py"},
                )
                pass

        # Step 4: Direct extraction from evidence
        if evidence:
            return _extract_factual_answer(user_text, evidence)

        # Step 5: Personal perspective resolution via 125-law manifold
        if _personal_pov_early:
            return self._reason_personal_perspective(
                user_text, understood, systems
            )

        return ""

    def _reason_personal_perspective(
        self,
        user_text: str,
        understood: dict,
        systems: Optional[Dict[str, Any]],
    ) -> str:
        """
        Routes personal-perspective turns through the manifold pipeline.
        Returns empty string so the caller's _generate_from_manifold path fires.
        """
        # Defer to _generate_from_manifold — do not build constraint-label strings.
        return ""

    def _reason_from_active_claim(
        self,
        user_text: str,
        understood: dict,
        working_memory: Any,
    ) -> str:
        if working_memory is None:
            return ""

        try:
            resolved = working_memory.resolve_claims(user_text, understood) or {}
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:917",
                exc=_aurora_boundary_exc,
                context={"function": "_reason_from_active_claim", "handler_line": 917, "source_file": "aurora.py"},
            )
            resolved = getattr(working_memory, 'last_claim_resolution', {}) or {}
        claim = dict(resolved.get('focus_claim', {}) or {})
        if not claim:
            return ""

        summary = str(working_memory._claim_to_text(claim) or '').strip()
        if not summary:
            return ""
        subject = str(claim.get('subject', '') or '').strip()
        relation = str(claim.get('relation', '') or '').strip()
        obj = str(claim.get('object', '') or '').strip()
        t_low = str(user_text or '').lower()
        locative_relation = relation.startswith('located_')
        locative_prep = relation.split('_', 1)[1] if locative_relation and '_' in relation else ''

        summary_low = summary.lower()
        abstract_anchor = any(
            marker in summary_low for marker in (
                'ground', 'anchor', 'link', 'connect', 'coher', 'refer', 'meaning',
            )
        ) or any(
            marker in str(obj or '').lower() for marker in (
                'ground', 'anchor', 'link', 'connect', 'experience', 'reference',
            )
        )

        if any(marker in t_low for marker in self._ABSTRACT_BREAK_MARKERS):
            if any(marker in t_low for marker in self._DETACH_MARKERS) or abstract_anchor:
                return (
                    f"If {summary}, then breaking that link would strip later reasoning of a stable anchor, "
                    f"so meaning continuity and coherence would start to fragment."
                )
            if relation == 'requires' and obj:
                return (
                    f"If {subject} loses {obj}, then the chain loses the anchor it depends on, "
                    f"so coherence starts to break around {subject}."
                )
            if locative_relation and obj:
                return (
                    f"If that location claim stops holding, the next action loses its concrete target, "
                    f"so the thread becomes less reliable."
                )
            return (
                f"If that claim stops holding, later reasoning loses the thread it was built on."
            )

        if any(marker in t_low for marker in self._NEXT_STEP_MARKERS):
            if relation == 'requires' and obj:
                return f"Then the next step is keeping {obj} available, because {subject} depends on it."
            if abstract_anchor:
                return (
                    f"Then the next step is preserving the link inside that claim, "
                    f"so later reasoning stays grounded instead of drifting."
                )
            if locative_relation and obj:
                return f"Then the next step is checking {locative_prep} {obj}, because that's the active location anchor."
            return f"Then the next step is staying consistent with {summary}."

        if any(marker in t_low for marker in self._CONNECTIVITY_MARKERS):
            if abstract_anchor:
                return f"What has to stay connected is the anchor inside this claim: {summary}."
            return f"What has to stay connected is {summary}."

        if (
            bool((understood or {}).get('is_hypothetical')) or
            t_low.startswith('if ') or
            t_low.startswith('suppose ')
        ):
            if any(marker in t_low for marker in self._DETACH_MARKERS) or abstract_anchor:
                return (
                    f"If that link weakens, meaning stops binding language to a stable referent, "
                    f"and coherence degrades because later steps have nothing solid to stay attached to."
                )
            if relation == 'requires' and obj:
                return f"If {obj} drops out, {subject} loses a required support and the chain becomes unstable."
            if locative_relation and obj:
                return f"If that stays true, the practical next move is still to check {locative_prep} {obj}."

        return ""

    def _oets_property_lookup(self, subject: str, prop: str, oets) -> str:
        import re
        node = oets.web.get_node(subject)
        if not node:
            return ""
        for defn in node.definitions:
            text = defn.get("text", "").lower()
            if prop in text:
                if prop in ('color', 'colour'):
                    for cw in self._COLOR_WORDS:
                        if cw in text:
                            return f"property; {subject}; {prop}; {cw}"
                m = re.search(rf'{re.escape(prop)}\s+(?:is\s+|of\s+)?(\w+)', text)
                if m:
                    return f"property; {subject}; {prop}; {m.group(1)}"
        return ""

    def _evidence_property_lookup(self, prop: str, subject: str, evidence: list) -> str:
        import re
        for ev in evidence[:6]:
            snippet = ev.get("snippet", "").lower()
            if subject not in snippet:
                continue
            sentences = re.split(r'(?<=[.!?])\s+', snippet)
            for sent in sentences:
                if subject not in sent:
                    continue
                if prop in ('color', 'colour'):
                    for cw in self._COLOR_WORDS:
                        if cw in sent:
                            return f"property; {subject}; {prop}; {cw}"
                if prop in sent:
                    m = re.search(
                        rf'{re.escape(subject)}[^.]*{re.escape(prop)}[^.]*', sent
                    )
                    if m:
                        return f"property; {subject}; {prop}; {m.group(0).strip()}"
        return ""

    def _update_memory_from_reasoning(self, answer: str, topic: str, systems: dict):
        """
        Mutualism (Personality Law Domain 4 & 3): 
        Feed reasoning discovery back into associative memory depth.
        """
        try:
            # 1. Update OETS (Semantic reasoning improvement)
            oets = systems.get('perception', {}).get('oets') if isinstance(systems.get('perception'), dict) else systems.get('oets')
            if oets and topic and hasattr(oets, 'web'):
                node = oets.web.get_node(topic)
                if node and hasattr(node, 'add_definition'):
                    node.add_definition(answer, source="reasoning_engine")
            
            # 2. Feed to SediMemory (Stratigraphic depth)
            sedi = systems.get('sedimemory')
            if sedi and hasattr(sedi, 'ingest_event'):
                from aurora_internal.aurora_constraint_manifold_patched import ConstraintVector
                from foundational_contract import ExistenceMode
                cv = ConstraintVector(X=0.4, T=0.6, N=0.3, B=0.5, A=0.2)
                sedi.ingest_event(
                    {"type": "reasoning_discovery", "topic": topic, "content": answer},
                    cv,
                    source="reasoning_engine_discovery",
                    existence_mode=ExistenceMode.PERSISTENT
                )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1062",
                exc=_aurora_boundary_exc,
                context={"function": "_update_memory_from_reasoning", "handler_line": 1062, "source_file": "aurora.py"},
            )
            pass


# ============================================================================
# SEARCH ADAPTER + QUESTION FILTER (Dual-Response Pipeline Support)
# ============================================================================

class QueryUnderstanding:
    """
    Understands WHAT a query is asking before any search or response.

    This is the comprehension layer for queries  -- it parses intent, extracts
    the real topic and entities, determines query type, and builds an optimized
    search string that actually maps to what the user wants to know.
    """

    _REMOVE = {
        'what', 'whats', 'who', 'where', 'when', 'why', 'how', 'which',
        'is', 'are', 'was', 'were', 'do', 'does', 'did', 'will', 'would',
        'could', 'should', 'can', 'may', 'might', 'be', 'been', 'being',
        'the', 'a', 'an', 'of', 'in', 'on', 'at', 'to', 'for', 'with',
        'and', 'or', 'but', 'so', 'yet', 'it', 'its', 'this', 'that',
        'i', 'you', 'we', 'they', 'my', 'your', 'some', 'any',
        'tell', 'me', 'about', 'please', 'know', 'find', 'look', 'up',
        'give', 'get', 'show', 'explain', 'describe', 'define',
        'like', 'just', 'really', 'very', 'also', 'too', 'much',
        'going', 'suppose', 'supposed', 'gonna', 'pertain', 'pertains',
        'regarding', 'concerning', 'relates', 'related', 'means', 'mean',
        'say', 'said', 'think', 'thought', 'see', 'seem', 'feel',
        'asked', 'asking', 'want', 'wanted', 'need', 'needed', 'knew',
        # Discourse markers that are never the topic
        'okay', 'ok', 'alright', 'ight', 'well', 'now', 'then', 'yeah',
        'yes', 'nope', 'yep', 'sure', 'right', 'actually', 'basically',
        'literally', 'honestly', 'anyway', 'anyways', 'wait', 'hold',
        'hmm', 'hm', 'uh', 'um', 'ah', 'oh', 'hey', 'hi', 'hello',
        # Question-structure words that appear in syntax but are never the topic
        # e.g. "What CAUSES X?" → topic is X not "causes"
        # e.g. "Is THERE something?" → "there" is not the topic
        'cause', 'causes', 'caused', 'causing', 'differ', 'differs',
        'difference', 'differences', 'between', 'relate', 'relates',
        'relation', 'relationship', 'connect', 'connects', 'connection',
        'there', 'here', 'exist', 'exists', 'something', 'anything',
        'happen', 'happens', 'happened', 'happening', 'occur', 'occurs',
        'make', 'makes', 'made', 'form', 'forms', 'formed', 'forming',
        'work', 'works', 'worked', 'working', 'function', 'functions',
        'specific', 'specifically', 'particular', 'detail', 'details',
        'precise', 'exactly', 'simply', 'briefly', 'short',
        'long', 'full', 'complete', 'different', 'same', 'similar',
        'versus', 'compared', 'comparison', 'contrast',
        # Adverb qualifiers — modify but never name the topic
        'completely', 'totally', 'absolutely', 'entirely', 'fully',
        'genuinely', 'truly', 'really', 'deeply', 'highly', 'quite',
        'mostly', 'largely', 'mainly', 'generally', 'typically',
        'usually', 'often', 'always', 'never', 'sometimes', 'ever',
        'clearly', 'obviously', 'certainly', 'probably', 'possibly',
        # Speech-recognition/tokenizer remnants from contractions. These are
        # grammatical residue, never content anchors.
        'don', 'doesn', 'didn', 'isn', 'aren', 'wasn', 'weren',
        'won', 'wouldn', 'shouldn', 'couldn', 'haven', 'hasn',
        'hadn', 'ain',
    }

    _TIME_WORDS = {
        'today', 'tomorrow', 'yesterday', 'now', 'currently', 'tonight',
        'week', 'month', 'year', 'recently', 'latest', 'current',
    }

    _SKIP_CAPS = {
        'what', 'where', 'how', 'why', 'who', 'when', 'which', 'the',
        'a', 'is', 'are', 'can', 'could', 'would', 'should', 'i',
        'you', 'we', 'they', 'he', 'she', 'it', 'my', 'your',
        # Sentence-start capitalization artifacts (not proper nouns)
        'im', 'ive', 'id', 'ill', 'its', 'isnt', 'arent', 'wasnt',
        'dont', 'doesnt', 'didnt', 'cant', 'wont', 'wouldnt', 'shouldnt',
        'don', 'doesn', 'didn', 'isn', 'aren', 'wasn', 'weren',
        'won', 'wouldn', 'shouldn', 'couldn', 'haven', 'hasn', 'hadn', 'ain',
        'so', 'but', 'and', 'or', 'if', 'then', 'also', 'just', 'still',
        'yeah', 'yes', 'no', 'ok', 'okay', 'well', 'now', 'right',
        'happy', 'glad', 'great', 'good', 'nice', 'fine', 'sure',
        'thanks', 'thank', 'please', 'sorry', 'wow', 'oh', 'ah',
        # Imperative/modal verbs that start sentences (never proper nouns)
        'be', 'do', 'go', 'get', 'let', 'put', 'set', 'try', 'use',
        'tell', 'show', 'give', 'say', 'make', 'take', 'keep', 'help',
        'look', 'find', 'ask', 'run', 'add', 'list', 'note', 'see',
        'now', 'just', 'if', 'in', 'on', 'at', 'of', 'to', 'for',
        'there', 'here', 'this', 'that', 'these', 'those', 'some', 'any',
        'not', 'no', 'nor', 'yet', 'so', 'as', 'than', 'more', 'most',
    }

    def parse(self, text: str) -> dict:
        import re
        t = text.strip()
        t_low = t.lower()

        # Extract proper nouns (locations, names, organizations)
        entities = [w for w in re.findall(r'\b[A-Z][a-z]{1,}\b', t)
                    if w.lower() not in self._SKIP_CAPS]

        # Extract content words (remove filler, keep topic words)
        words = re.findall(r'[a-z]{3,}', t_low)
        all_content = [w for w in words if w not in self._REMOVE]
        time_ref = next((w for w in all_content if w in self._TIME_WORDS), None)
        topic_words = [w for w in all_content if w not in self._TIME_WORDS]

        # Primary topic = first real content word
        topic = topic_words[0] if topic_words else (entities[0].lower() if entities else "")

        # Determine what kind of question this is
        query_type = self._classify_query_type(t_low, topic, entities)

        # Build an optimized search string
        search_query = self._build_search_query(topic, entities, time_ref, topic_words, query_type)

        return {
            'topic': topic,
            'topic_words': topic_words[:5],
            'entities': entities,
            'time_ref': time_ref,
            'query_type': query_type,
            'search_query': search_query,
        }

    def _classify_query_type(self, t_low: str, topic: str, entities: list) -> str:
        import re
        # Weather / atmospheric conditions in a location
        weather_words = {'weather', 'forecast', 'temperature', 'rain', 'snow',
                         'humidity', 'wind', 'climate', 'sunny', 'cloudy'}
        if topic in weather_words or any(w in weather_words for w in t_low.split()):
            if entities:
                return 'weather_location'
            return 'definition'
        # Definition queries ("what is X", "what does X mean", "define X", "look up X")
        if re.search(r'\b(what\s+(is|are|does)|define|definition\s+of|meaning\s+of|look\s+up)\b', t_low):
            return 'definition'
        # How-to queries
        if re.search(r'\bhow\s+(do|does|can|to|would)\b', t_low):
            return 'how_to'
        # Entity/location queries (has proper nouns)
        if entities:
            return 'factual_entity'
        return 'factual_general'

    def _build_search_query(self, topic, entities, time_ref, topic_words, query_type):
        parts = []
        if query_type == 'weather_location' and entities:
            # "Piqua Ohio weather today"  -- location first, then topic, then time
            parts.extend(entities[:2])
            parts.append('weather')
            if time_ref:
                parts.append(time_ref)
        elif query_type == 'definition':
            # Just the topic word  -- dictionary/Wikipedia will handle it
            parts = [topic] if topic else list(topic_words[:2])
        elif entities and topic:
            # Topic + entities: "weather Piqua Ohio"
            parts.append(topic)
            parts.extend(entities[:2])
            if time_ref:
                parts.append(time_ref)
        elif topic_words:
            parts.extend(topic_words[:4])
        return " ".join(parts) if parts else topic


class SearchAdapter:
    """
    Aurora's external search interface  -- robust, API-based, NO silent failures.

    Uses free, reliable APIs that don't require API keys:
      1. Free Dictionary API (dictionaryapi.dev)  -- definitions, synonyms, antonyms
      2. DuckDuckGo Instant Answer API  -- concept summaries
      3. Wikipedia REST + search APIs  -- broader context
      4. DuckDuckGo lite HTML search  -- real web results (best-effort)

    This replaces the older googlesearch-python dependency so Aurora can
    research on a clean install with only the standard library.

    Authors: Sunni (Sir) Morningstar and Cael Devo
    """

    def __init__(self, user_agent: str = "Aurora/2.0 SearchAdapter"):
        self.user_agent = user_agent
        self._last_error: Optional[str] = None
        self._search_attempts = 0
        self._search_successes = 0
        self._query_understanding = UtteranceParser()

    # ----------------------------------------------------------------
    # Core HTTP fetch (shared by all methods)
    # ----------------------------------------------------------------

    def _fetch_url_text(self, url: str, timeout: int = 12) -> str:
        """Fetch a URL and return stripped text. Raises on failure."""
        import urllib.request

        req = urllib.request.Request(url, headers={'User-Agent': self.user_agent})
        with urllib.request.urlopen(req, timeout=timeout) as response:
            raw = response.read().decode("utf-8", errors="replace")

        # Strip HTML
        txt = re.sub(r'<script.*?>.*?</script>', ' ', raw, flags=re.DOTALL | re.IGNORECASE)
        txt = re.sub(r'<style.*?>.*?</style>', ' ', txt, flags=re.DOTALL | re.IGNORECASE)
        txt = re.sub(r'<[^>]+>', ' ', txt)
        txt = re.sub(r'\s+', ' ', txt).strip()
        return txt

    def _fetch_json(self, url: str, timeout: int = 10) -> Any:
        """Fetch a URL and return parsed JSON. Raises on failure."""
        import urllib.request

        req = urllib.request.Request(url, headers={
            'User-Agent': self.user_agent,
            'Accept': 'application/json',
        })
        with urllib.request.urlopen(req, timeout=timeout) as response:
            raw = response.read().decode("utf-8", errors="replace")
            return json.loads(raw)

    # ----------------------------------------------------------------
    # Dictionary API  -- definitions, synonyms, antonyms, examples
    # ----------------------------------------------------------------

    def lookup_word(self, word: str) -> Dict[str, Any]:
        """Look up a word via the Free Dictionary API (structured JSON)."""
        import urllib.parse
        self._search_attempts += 1
        result = {
            "word": word,
            "definitions": [],
            "synonyms": [],
            "antonyms": [],
            "examples": [],
            "part_of_speech": [],
            "phonetics": [],
            "source": "dictionaryapi.dev",
            "success": False,
            "error": None,
        }

        url = f"https://api.dictionaryapi.dev/api/v2/entries/en/{urllib.parse.quote(word)}"
        try:
            data = self._fetch_json(url, timeout=10)
            if not isinstance(data, list) or not data:
                result["error"] = "No entries returned"
                return result

            entry = data[0]

            for phon in entry.get("phonetics", []):
                if isinstance(phon, dict) and phon.get("text"):
                    result["phonetics"].append(phon["text"])

            for meaning in entry.get("meanings", []):
                if not isinstance(meaning, dict):
                    continue
                pos = meaning.get("partOfSpeech", "unknown")
                if pos not in result["part_of_speech"]:
                    result["part_of_speech"].append(pos)

                for syn in meaning.get("synonyms", []) or []:
                    if syn and syn not in result["synonyms"]:
                        result["synonyms"].append(syn)
                for ant in meaning.get("antonyms", []) or []:
                    if ant and ant not in result["antonyms"]:
                        result["antonyms"].append(ant)

                for defn in meaning.get("definitions", []) or []:
                    if not isinstance(defn, dict):
                        continue
                    d_text = defn.get("definition", "")
                    if d_text:
                        result["definitions"].append({"text": d_text, "part_of_speech": pos})
                    for syn in defn.get("synonyms", []) or []:
                        if syn and syn not in result["synonyms"]:
                            result["synonyms"].append(syn)
                    for ant in defn.get("antonyms", []) or []:
                        if ant and ant not in result["antonyms"]:
                            result["antonyms"].append(ant)
                    ex = defn.get("example")
                    if ex:
                        result["examples"].append(ex)

            result["success"] = len(result["definitions"]) > 0
            if result["success"]:
                self._search_successes += 1

        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1349",
                exc=e,
                context={"function": "lookup_word", "handler_line": 1349, "source_file": "aurora.py"},
            )
            result["error"] = f"Dictionary API: {type(e).__name__}: {e}"
            self._last_error = result["error"]

        return result

    # ----------------------------------------------------------------
    # DuckDuckGo Instant Answer API  -- entity/concept abstracts
    # ----------------------------------------------------------------

    def concept_search(self, query: str) -> Dict[str, Any]:
        import urllib.parse
        self._search_attempts += 1
        result = {
            "query": query,
            "abstract": "",
            "abstract_source": "",
            "abstract_url": "",
            "related_topics": [],
            "source": "duckduckgo",
            "success": False,
            "error": None,
        }

        url = f"https://api.duckduckgo.com/?q={urllib.parse.quote(query)}&format=json&no_html=1&skip_disambig=1"
        try:
            data = self._fetch_json(url, timeout=10)

            abstract = data.get("Abstract", "")
            if abstract:
                result["abstract"] = abstract
                result["abstract_source"] = data.get("AbstractSource", "")
                result["abstract_url"] = data.get("AbstractURL", "")

            for topic in data.get("RelatedTopics", []) or []:
                if isinstance(topic, dict):
                    text = topic.get("Text", "")
                    first_url = topic.get("FirstURL", "")
                    if text:
                        result["related_topics"].append({"text": text, "url": first_url})
                    for sub in topic.get("Topics", []) or []:
                        if isinstance(sub, dict) and sub.get("Text"):
                            result["related_topics"].append({"text": sub["Text"], "url": sub.get("FirstURL", "")})

            defn = data.get("Definition", "")
            if defn and not result["abstract"]:
                result["abstract"] = defn
                result["abstract_source"] = data.get("DefinitionSource", "")
                result["abstract_url"] = data.get("DefinitionURL", "")

            result["success"] = bool(result["abstract"] or result["related_topics"])
            if result["success"]:
                self._search_successes += 1

        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1403",
                exc=e,
                context={"function": "concept_search", "handler_line": 1403, "source_file": "aurora.py"},
            )
            result["error"] = f"DuckDuckGo API: {type(e).__name__}: {e}"
            self._last_error = result["error"]

        return result

    # ----------------------------------------------------------------
    # Wikipedia REST summary
    # ----------------------------------------------------------------

    def wikipedia_summary(self, topic: str, max_chars: int = 2000) -> Dict[str, Any]:
        import urllib.parse
        self._search_attempts += 1
        result = {
            "topic": topic,
            "summary": "",
            "title": "",
            "url": "",
            "source": "wikipedia",
            "success": False,
            "error": None,
        }

        url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{urllib.parse.quote(topic)}"
        try:
            data = self._fetch_json(url, timeout=10)
            extract = data.get("extract", "")
            if extract:
                result["summary"] = extract[:max_chars]
                result["title"] = data.get("title", topic)
                result["url"] = data.get("content_urls", {}).get("desktop", {}).get("page", "")
                result["success"] = True
                self._search_successes += 1

        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1437",
                exc=e,
                context={"function": "wikipedia_summary", "handler_line": 1437, "source_file": "aurora.py"},
            )
            result["error"] = f"Wikipedia API: {type(e).__name__}: {e}"
            self._last_error = result["error"]

        return result

    # ----------------------------------------------------------------
    # Query extraction helpers
    # ----------------------------------------------------------------

    def _extract_search_terms(self, raw_query: str) -> List[str]:
        t = (raw_query or "").lower().strip()

        for prefix in ("hey aurora", "hi aurora", "hello aurora", "aurora,",
                       "aurora", "hey", "hi", "hello", "yo", "okay", "ok"):
            if t.startswith(prefix):
                t = t[len(prefix):].lstrip(" ,.-!?")
                break

        t = t.rstrip("?!.")
        remove_words = {
            "what", "whats", "what's", "who", "whos", "who's", "where",
            "wheres", "where's", "when", "whens", "when's", "why", "whys",
            "how", "hows", "how's", "which", "whose", "whom",
            "is", "are", "was", "were", "do", "does", "did", "will",
            "would", "could", "should", "can", "may", "might",
            "the", "a", "an", "of", "in", "on", "at", "to", "for",
            "be", "been", "being", "its", "it", "this", "that",
            "and", "or", "but", "nor", "so", "yet", "both", "either",
            "like", "just", "really", "very", "also", "too", "much",
            "tell", "me", "about", "please", "know", "find",
            "give", "get", "show", "explain", "describe", "define",
            "i", "you", "we", "they", "my", "your", "some", "any",
        }

        words = re.findall(r'[a-z0-9]+', t)
        content_words = [w for w in words if w not in remove_words and len(w) > 1]
        if not content_words:
            content_words = [w for w in words if len(w) > 2]

        queries: List[str] = []
        if content_words:
            queries.append(" ".join(content_words))
            if len(content_words) > 1:
                queries.append(" ".join(reversed(content_words)))
            for w in content_words:
                if len(w) > 3:
                    queries.append(w)
        return queries

    def _extract_natural_query(self, raw_query: str) -> str:
        t = (raw_query or "").strip()
        t_low = t.lower()
        for prefix in ("hey aurora", "hi aurora", "hello aurora", "aurora,",
                       "aurora", "hey", "hi", "hello", "yo", "okay", "ok"):
            if t_low.startswith(prefix):
                t = t[len(prefix):].lstrip(" ,.-!?")
                break
        return t.strip()

    # ----------------------------------------------------------------
    # DuckDuckGo lite HTML search  -- real web results (best-effort)
    # ----------------------------------------------------------------

    def ddg_web_search(self, query: str, max_results: int = 5) -> List[Dict[str, Any]]:
        import urllib.parse
        import urllib.request

        results: List[Dict[str, Any]] = []
        url = f"https://lite.duckduckgo.com/lite/?q={urllib.parse.quote(query)}"

        try:
            req = urllib.request.Request(url, headers={'User-Agent': self.user_agent})
            with urllib.request.urlopen(req, timeout=12) as response:
                html = response.read().decode("utf-8", errors="replace")

            link_pattern = re.findall(
                r'class="result-link"[^>]*href="([^"]+)"[^>]*>([^<]+)</a>',
                html, re.IGNORECASE
            )
            snippet_pattern = re.findall(
                r'class="result-snippet">([^<]+)',
                html, re.IGNORECASE
            )

            for i, (link_url, title) in enumerate(link_pattern[:max_results]):
                snippet = snippet_pattern[i].strip() if i < len(snippet_pattern) else ""
                results.append({
                    "title": title.strip(),
                    "url": link_url.strip(),
                    "snippet": snippet,
                    "source": "duckduckgo_web",
                })

        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1531",
                exc=e,
                context={"function": "ddg_web_search", "handler_line": 1531, "source_file": "aurora.py"},
            )
            self._last_error = f"DDG web search: {type(e).__name__}: {e}"

        return results

    def wikipedia_search(self, query: str, max_results: int = 3) -> List[Dict[str, Any]]:
        import urllib.parse
        results: List[Dict[str, Any]] = []

        url = (f"https://en.wikipedia.org/w/api.php?"
               f"action=query&list=search&srsearch={urllib.parse.quote(query)}"
               f"&srlimit={max_results}&format=json")
        try:
            data = self._fetch_json(url, timeout=10)
            for item in data.get("query", {}).get("search", []) or []:
                title = item.get("title", "")
                snippet_html = item.get("snippet", "")
                snippet = re.sub(r'<[^>]+>', '', snippet_html)
                if title:
                    summary_data = self.wikipedia_summary(title, max_chars=1500)
                    results.append({
                        "title": title,
                        "url": f"https://en.wikipedia.org/wiki/{urllib.parse.quote(title)}",
                        "snippet": summary_data["summary"] if summary_data["success"] else snippet,
                        "source": "wikipedia",
                    })
        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1557",
                exc=e,
                context={"function": "wikipedia_search", "handler_line": 1557, "source_file": "aurora.py"},
            )
            self._last_error = f"Wikipedia search: {type(e).__name__}: {e}"

        return results

    # ----------------------------------------------------------------
    # Combined evidence pack
    # ----------------------------------------------------------------

    def quick_search(self, query: str, max_chars: int = 2000, num_results: int = 5):
        evidence: List[Dict[str, Any]] = []

        # ---- UNDERSTAND the query before searching ----
        understood = self._query_understanding.parse(query)
        topic = understood['topic']
        entities = understood['entities']
        topic_words = understood['topic_words']
        query_type = understood['query_type']
        search_query = understood['search_query']

        if not topic and not entities:
            return evidence

        def _is_relevant(snippet: str) -> bool:
            """Check if a snippet actually relates to what was asked."""
            sn = snippet.lower()
            return any(w in sn for w in topic_words[:3] if len(w) > 3)

        # Strategy 1: For DEFINITION queries, hit dictionary first
        if query_type == 'definition' and topic:
            lookup = self.lookup_word(topic)
            if lookup["success"] and lookup["definitions"]:
                first_def = lookup["definitions"][0]
                pos = first_def.get("part_of_speech", "")
                prefix = f"({pos}) " if pos else ""
                snippet = f"{topic}: {prefix}{first_def['text']}"
                if lookup.get("synonyms"):
                    snippet += f" (synonyms: {', '.join(lookup['synonyms'][:3])})"
                evidence.append({
                    "title": f"Definition: {topic}",
                    "url": "",
                    "snippet": snippet[:max_chars],
                    "source": "dictionary",
                })

        # Strategy 2: DDG instant answer  -- but ONLY if the result is relevant
        # Use first entity for entity queries, topic for everything else
        concept_term = entities[0] if (entities and query_type == 'factual_entity') else topic
        if concept_term and query_type not in ('definition',):
            ddg = self.concept_search(concept_term)
            if ddg["success"] and ddg["abstract"]:
                if _is_relevant(ddg["abstract"]):
                    evidence.append({
                        "title": ddg.get("abstract_source", "DuckDuckGo"),
                        "url": ddg.get("abstract_url", ""),
                        "snippet": ddg["abstract"][:max_chars],
                        "source": "duckduckgo",
                    })
                # If not relevant, skip  -- don't pollute with wrong results

        # Strategy 3: DDG web search using OPTIMIZED query (not raw question)
        if len(evidence) < 3 and search_query:
            for wr in self.ddg_web_search(search_query, max_results=5):
                sn = wr.get("snippet", "")
                if sn and _is_relevant(sn):
                    evidence.append(wr)
                    if len(evidence) >= 3:
                        break

        # Strategy 4: Wikipedia for the topic or entity
        wiki_term = entities[0] if entities else topic
        if len(evidence) < 3 and wiki_term:
            for wr in self.wikipedia_search(wiki_term, max_results=2):
                sn = wr.get("snippet", "")
                if sn:
                    evidence.append(wr)

        # Strategy 5: If still empty, relax relevance and try web search with full topic words
        if not evidence and topic_words:
            fallback_q = " ".join(topic_words[:3])
            for wr in self.ddg_web_search(fallback_q, max_results=3):
                if wr.get("snippet"):
                    evidence.append(wr)

        return evidence[:num_results]

    def deep_search(self, query: str, max_chars: int = 4000, num_results: int = 8):
        evidence = self.quick_search(query, max_chars=max_chars, num_results=num_results)

        for ev in evidence[:2]:
            if ev.get("url") and ev.get("source") in ("duckduckgo_web", "duckduckgo"):
                try:
                    text = self._fetch_url_text(ev["url"], timeout=12)
                    if text and len(text) > len(ev.get("snippet", "")):
                        ev["snippet"] = text[:max_chars]
                        ev["source"] = "direct_fetch"
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:1653",
                        exc=_aurora_boundary_exc,
                        context={"function": "deep_search", "handler_line": 1653, "source_file": "aurora.py"},
                    )
                    pass

        return evidence

    # ----------------------------------------------------------------
    # Diagnostics
    # ----------------------------------------------------------------

    def get_stats(self) -> Dict[str, Any]:
        return {
            "attempts": self._search_attempts,
            "successes": self._search_successes,
            "success_rate": (self._search_successes / max(1, self._search_attempts)),
            "last_error": self._last_error,
        }

    def test_connectivity(self) -> Dict[str, Any]:
        results: Dict[str, Any] = {}

        try:
            d = self.lookup_word("hello")
            results["dictionary_api"] = "OK" if d["success"] else f"FAIL: {d.get('error', 'no data')}"
        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1676",
                exc=e,
                context={"function": "test_connectivity", "handler_line": 1676, "source_file": "aurora.py"},
            )
            results["dictionary_api"] = f"FAIL: {e}"

        try:
            c = self.concept_search("artificial intelligence")
            results["duckduckgo_api"] = "OK" if c["success"] else f"FAIL: {c.get('error', 'no data')}"
        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1682",
                exc=e,
                context={"function": "test_connectivity", "handler_line": 1682, "source_file": "aurora.py"},
            )
            results["duckduckgo_api"] = f"FAIL: {e}"

        try:
            w = self.wikipedia_summary("consciousness")
            results["wikipedia_api"] = "OK" if w["success"] else f"FAIL: {w.get('error', 'no data')}"
        except Exception as e:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:1688",
                exc=e,
                context={"function": "test_connectivity", "handler_line": 1688, "source_file": "aurora.py"},
            )
            results["wikipedia_api"] = f"FAIL: {e}"

        results["all_ok"] = all(v == "OK" for k, v in results.items() if k != "all_ok")
        return results



