    def project(self, parsed: dict, systems: dict) -> Dict[str, float]:
        """
        Return {X, T, N, B, A} activation for this utterance in current system state.

        parsed  — output of UtteranceParser.parse()
        systems — live Aurora systems dict (lattice, genealogy, dimensional, perception)
        """
        ax: Dict[str, float] = {"X": 0.0, "T": 0.0, "N": 0.0, "B": 0.0, "A": 0.0}

        # --- 1a. Pragmatic signal pass (roles → axis weights) --------------------
        signals = parsed.get("pragmatic_signals", [])   # list of (role_str, span) tuples
        sig_count = max(1, len(signals))
        for role_str, _span in signals:
            role_weights = self._ROLE_AXIS.get(role_str)
            if role_weights:
                for letter, w in role_weights.items():
                    ax[letter] += w / sig_count

        # --- 1b. Semantic word pass — domain-specific words added to utterance vec -
        # Words like "understand"→A, "meaning"→B, "purpose"→N carry strong
        # constraint-domain signal. They are added to ax at 1.0× weight (same
        # scale as a pragmatic signal) before normalization so the utterance
        # sub-vector reflects both HOW the user is speaking (pragmatic roles)
        # and WHAT they are speaking about (semantic domain).
        raw_text = str(parsed.get("raw_text", "") or parsed.get("text", "") or "").lower()
        topic_words = [str(w).lower().strip() for w in list(parsed.get("topic_words", []) or [])]
        all_words = set(topic_words) | set(re.findall(r"[a-z]{4,}", raw_text))
        for word in all_words:
            sem_weights = self._SEMANTIC_WORD_AXIS.get(word)
            if sem_weights:
                for letter, w in sem_weights.items():
                    ax[letter] += w

        # Normalise the lexical/pragmatic sub-vector.
        _total = sum(ax.values()) or 1.0
        lexical_vec = {k: v / _total for k, v in ax.items()}

        # --- 1c. Relational configuration pass ----------------------------------
        # The proposition's structure carries stronger semantic authority than
        # isolated words.  Its vector is derived from the root operations needed
        # to preserve entities, relation, unknown, boundary and authorship.
        try:
            from aurora_internal.aurora_constraint_semantic_continuity import relational_axis_vector
            relational_vec = relational_axis_vector(parsed.get("relational_form") or {})
        except Exception:
            relational_vec = {k: 0.2 for k in ("X", "T", "N", "B", "A")}
        utt_vec = {
            k: (0.42 * float(lexical_vec.get(k, 0.2))) +
               (0.58 * float(relational_vec.get(k, 0.2)))
            for k in ("X", "T", "N", "B", "A")
        }
        _utt_total = sum(utt_vec.values()) or 1.0
        utt_vec = {k: v / _utt_total for k, v in utt_vec.items()}

        # --- 2. IVM phase signal (toroidal polarity → axis receptivity) ----------
        # A toroidal axis near polarity=0 (throat of the torus) is unsettled —
        # it is most receptive to new activation.  Near ±1 it is settled.
        ivm_vec: Dict[str, float] = {"X": 0.5, "T": 0.5, "N": 0.5, "B": 0.5, "A": 0.5}
        lattice = systems.get("lattice")
        if lattice:
            try:
                ivm_axes = getattr(lattice, "axes", {}) or {}
                for aname, letter in self._AXIS_NAME_MAP.items():
                    ta = ivm_axes.get(aname)
                    if ta is not None:
                        polarity = float(getattr(ta, "polarity", 0.0))
                        # receptivity: high when polarity near 0 (transition)
                        ivm_vec[letter] = 1.0 - abs(polarity) * 0.5
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:3351",
                    exc=_aurora_boundary_exc,
                    context={"function": "project", "handler_line": 3351, "source_file": "aurora.py"},
                )
                pass

        # --- 3. Evolutionary signal (genealogy) — two complementary sub-signals ---
        # 3a. Phase reliability: correction factors from PressureComplexityCurve.
        #     Tells whether each axis is in a consolidating (>1.0) or noisy (<1.0) phase.
        #     Normalized to ~[0,1] by dividing correction (range ~0.45–1.15) by 2.0.
        gen_vec: Dict[str, float] = {"X": 1.0, "T": 1.0, "N": 1.0, "B": 1.0, "A": 1.0}
        # 3b. Active evolution: axis_relief_state() — which axes are accumulating
        #     promoted links right now (developmental momentum, already 0–1 normalized).
        relief_vec: Dict[str, float] = {"X": 0.0, "T": 0.0, "N": 0.0, "B": 0.0, "A": 0.0}
        genealogy = systems.get("genealogy")
        if genealogy:
            try:
                if hasattr(genealogy, "pressure_orientation"):
                    orient = genealogy.pressure_orientation() or {}
                elif isinstance(genealogy, dict):
                    orient = genealogy.get("pressure_orientation") or genealogy.get("orientation") or {}
                else:
                    orient = {}
                for letter, corr in orient.items():
                    if letter in gen_vec:
                        gen_vec[letter] = float(corr)
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:3369",
                    exc=_aurora_boundary_exc,
                    context={"function": "project", "handler_line": 3369, "source_file": "aurora.py"},
                )
                pass
            try:
                if hasattr(genealogy, "axis_relief_state"):
                    relief_vec = genealogy.axis_relief_state()
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:3374",
                    exc=_aurora_boundary_exc,
                    context={"function": "project", "handler_line": 3374, "source_file": "aurora.py"},
                )
                pass

        # --- 4. Contextual signal (DCE situational frame axis weights) -----------
        # ConsciousnessEngine holds the DCEAssembly (.dce); DimensionalSystems does not.
        # Frame success_rate weights confidence: high-success frames guide axes more strongly.
        dce_vec: Dict[str, float] = {"X": 0.2, "T": 0.2, "N": 0.2, "B": 0.2, "A": 0.2}
        try:
            consciousness = systems.get("consciousness")
            if consciousness:
                dce = getattr(consciousness, "dce", None)
                if dce:
                    frame_name = getattr(dce, "last_frame_name", "balanced")
                    frame = dce.frames.get(frame_name) if hasattr(dce, "frames") else None
                    if frame:
                        fw = getattr(frame, "axis_weights", {}) or {}
                        sr = max(0.1, float(getattr(frame, "success_rate", 0.5)))
                        for fname, w in fw.items():
                            letter = self._AXIS_NAME_MAP.get(fname, fname)
                            if letter in dce_vec:
                                # Blend toward flat 0.2 when success_rate is low
                                dce_vec[letter] = float(w) * sr + 0.2 * (1.0 - sr)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:3396",
                exc=_aurora_boundary_exc,
                context={"function": "project", "handler_line": 3396, "source_file": "aurora.py"},
            )
            pass

        # --- 5. Blend: 55% utterance (pragmatic + semantic words combined),
        #            20% IVM phase, 10% phase-reliability,
        #            5% evolution-momentum, 10% DCE ----------------------------
        combined: Dict[str, float] = {}
        for letter in ("X", "T", "N", "B", "A"):
            combined[letter] = (
                0.55 * utt_vec[letter]
                + 0.20 * ivm_vec[letter]
                + 0.10 * gen_vec.get(letter, 1.0) / 2.0   # phase reliability, normalized to ~[0,1]
                + 0.05 * relief_vec.get(letter, 0.0)       # active evolution momentum [0,1]
                + 0.10 * dce_vec[letter]
            )

        # Re-normalise
        _total = sum(combined.values()) or 1.0
        return {k: round(v / _total, 4) for k, v in combined.items()}

    def dominant(self, activation: Dict[str, float]) -> str:
        """Return the single most active axis letter."""
        return max(activation, key=lambda k: activation[k])


