def _absorb_definition_into_self_model(
    anchor: str,
    definition_text: str,
    systems: Dict[str, Any],
) -> Optional[str]:
    """
    After Aurora retrieves a Poedex definition, check if it describes a capability
    she already possesses. If so:
      1. Ground the concept in OETS as a semantic node with the definition.
      2. Write a first-person self-note to working_memory mapping the concept to
         her specific internal systems so she can refer to it in responses.

    Returns a short self-referential note string if a mapping was found, else None.
    """
    if not anchor or not definition_text:
        return None

    anchor_low = str(anchor).lower().strip()
    anchor_kw = set(re.findall(r'[a-z]{4,}', anchor_low))

    # Find matching capability keywords
    matched_systems: List[str] = []
    for kw, sys_names in _AURORA_SELF_CAPABILITY_MAP.items():
        if kw in anchor_low or anchor_low in kw:
            for sn in sys_names:
                if sn not in matched_systems:
                    matched_systems.append(sn)
        elif anchor_kw & {kw}:
            for sn in sys_names:
                if sn not in matched_systems:
                    matched_systems.append(sn)

    # Filter to systems that are actually present
    present: List[str] = []
    for sn in matched_systems:
        if sn == "oets":
            perception = systems.get("perception")
            if getattr(perception, "oets", None) is not None:
                present.append(sn)
        elif systems.get(sn) is not None:
            present.append(sn)

    # 1. Ground in OETS
    try:
        perception = systems.get("perception")
        oets = getattr(perception, "oets", None) if perception is not None else None
        if oets is not None and hasattr(oets, "web") and hasattr(oets.web, "add_node"):
            _node = oets.web.add_node(anchor_low, "concept", meaning=definition_text)
            if _node is not None and hasattr(_node, "add_definition"):
                _node.add_definition(definition_text, source="poedex")
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9362",
            exc=_aurora_boundary_exc,
            context={"function": "_absorb_definition_into_self_model", "handler_line": 9362, "source_file": "aurora.py"},
        )
        pass

    if not present:
        return None

    # 2. Build self-referential note
    labels = [_AURORA_SYSTEM_LABELS.get(sn, sn) for sn in present[:3]]
    note = (
        f"self-knowledge; mapping; {anchor}; capabilities; "
        f"{', '.join(labels)}; active part; how I function"
    )

    # 3. Write to working memory
    try:
        wm = systems.get("working_memory")
        if wm is not None:
            if hasattr(wm, "note_user_facts"):
                # Use the factual note path — frame it as a first-person assertion
                # about Aurora's own nature so it is stored as a known claim.
                wm.note_user_facts(f"Aurora has {anchor}: {', '.join(labels)}")
            # Also stash directly in pipeline state for next DCE evidence pass
            _ps = getattr(wm, "_pipeline_context", None)
            if isinstance(_ps, dict):
                _ps["aurora_self_grounding"] = {
                    "concept": anchor,
                    "systems": present[:3],
                    "note": note,
                }
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9391",
            exc=_aurora_boundary_exc,
            context={"function": "_absorb_definition_into_self_model", "handler_line": 9391, "source_file": "aurora.py"},
        )
        pass

    # 4. Record in systems dict for this turn (DCE can pick it up from evidence)
    try:
        _prior = list(systems.get("_self_groundings", []) or [])
        _prior.append({"concept": anchor, "systems": present[:3], "note": note})
        systems["_self_groundings"] = _prior[-6:]  # keep last 6
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9399",
            exc=_aurora_boundary_exc,
            context={"function": "_absorb_definition_into_self_model", "handler_line": 9399, "source_file": "aurora.py"},
        )
        pass

    return note


def _try_poedex_lookup(topic: str, systems: dict, timeout: float = 1.5,
                       use_researcher: bool = False) -> str:
    """
    Consult Aurora's Poedex for a topic.

    1. Checks poedex_lessons.json for a bound lesson matching the topic (instant).
    2. If the room appears to be running, submits to the queue and waits:
       - use_researcher=False (default): cat="define", internal Observer, timeout=1.5s
       - use_researcher=True:            cat="external", Researcher GPT-4o, timeout=8s
         Use this when Aurora is about to decline — the extra wait is worth it.

    Returns the result string (≤600 chars), or '' if nothing is found.
    """
    try:
        import time as _t
        from pathlib import Path as _P
        _sd = _P(str((systems or {}).get("state_dir") or (_P(__file__).parent / "aurora_state")))

        # ── 0. Direct callable (daemon registered systems['poedex']) ─────────
        # When the daemon has wired _poedex_ask into systems, use it directly
        # — no filesystem queue overhead, correct per-request file isolation.
        _poedex_direct = systems.get('poedex') if isinstance(systems, dict) else None
        if _poedex_direct is not None and callable(_poedex_direct):
            try:
                _direct_cat = "researcher" if use_researcher else "define"
                _direct_to  = (35.0 if use_researcher else timeout)
                _direct_res = _poedex_direct(topic, cat=_direct_cat, lane="self",
                                             timeout=_direct_to)
                if _direct_res:
                    if use_researcher:
                        _digest_research_text(str(_direct_res), systems, source_text=topic, source="poedex")
                    return str(_direct_res)
                # If researcher returned nothing, fall through to bound lessons
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:9436",
                    exc=_aurora_boundary_exc,
                    context={"function": "_try_poedex_lookup", "handler_line": 9436, "source_file": "aurora.py"},
                )
                pass  # fall through to file-based path

        # ── 1. Bound lessons (instant, no room needed) ───────────────────────
        _lessons_path = _sd / "poedex_lessons.json"
        if _lessons_path.exists():
            try:
                _lessons = json.loads(_lessons_path.read_text() or '[]')
                _topic_low = topic.lower()
                # Extract significant keywords from topic (length ≥ 4)
                _topic_kw = set(re.findall(r'[a-z]{4,}', _topic_low))
                for _les in _lessons:
                    _q = str(_les.get('question', '') or '').lower()
                    _r = str(_les.get('lesson', '') or '').strip()
                    if not (_r and len(_r) > 20):
                        continue
                    # Exact containment check
                    if _topic_low and (_topic_low in _q or _q in _topic_low):
                        return _r
                    # Keyword overlap: ≥2 topic keywords appear in question or lesson
                    _q_kw = set(re.findall(r'[a-z]{4,}', _q))
                    _r_kw = set(re.findall(r'[a-z]{4,}', _r.lower()))
                    if _topic_kw and len(_topic_kw & (_q_kw | _r_kw)) >= max(2, len(_topic_kw) // 2):
                        return _r
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:9460",
                    exc=_aurora_boundary_exc,
                    context={"function": "_try_poedex_lookup", "handler_line": 9460, "source_file": "aurora.py"},
                )
                pass

        # ── 2. Queue-based lookup (only if room is likely running) ───────────
        _queue_dir  = _sd / "poedex_queue"
        _result_dir = _sd / "poedex_results"

        # Room is likely running if the result directory has been touched recently
        # (fallback: check the legacy result file)
        _room_likely_up = False
        if _result_dir.exists():
            try:
                _age = _t.time() - _result_dir.stat().st_mtime
                _room_likely_up = _age < 300
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:9474",
                    exc=_aurora_boundary_exc,
                    context={"function": "_try_poedex_lookup", "handler_line": 9474, "source_file": "aurora.py"},
                )
                pass
        if not _room_likely_up:
            _legacy_result = _sd / "poedex_query_result.json"
            if _legacy_result.exists():
                try:
                    _age = _t.time() - _legacy_result.stat().st_mtime
                    _room_likely_up = _age < 300
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:9482",
                        exc=_aurora_boundary_exc,
                        context={"function": "_try_poedex_lookup", "handler_line": 9482, "source_file": "aurora.py"},
                    )
                    pass

        if not _room_likely_up:
            return ''

        # Per-request files — no single-slot race condition
        _cat     = "external" if use_researcher else "define"
        _poll_to = 35.0 if use_researcher else timeout   # match daemon's researcher ceiling
        import os as _os
        qid = f"poe_{_t.time():.4f}_{_os.getpid()}"
        try:
            _queue_dir.mkdir(parents=True, exist_ok=True)
            _result_dir.mkdir(parents=True, exist_ok=True)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9496",
                exc=_aurora_boundary_exc,
                context={"function": "_try_poedex_lookup", "handler_line": 9496, "source_file": "aurora.py"},
            )
            return ''
        _query_path  = _queue_dir  / f"{qid}.json"
        _result_path = _result_dir / f"{qid}.json"
        _query_path.write_text(json.dumps({
            "id":        qid,
            "question":  topic,
            "cat":       _cat,
            "lane":      "self",
            "status":    "pending",
            "submitted": _t.time(),
        }, indent=2))

        deadline = _t.time() + _poll_to
        while _t.time() < deadline:
            _t.sleep(0.3)
            if _result_path.exists():
                try:
                    _r = json.loads(_result_path.read_text() or '{}')
                    if _r.get('id') == qid and _r.get('status') == 'done':
                        _txt = str(_r.get('result', '') or '').strip()
                        try: _result_path.unlink(missing_ok=True)
                        except Exception as _aurora_boundary_exc:
                            _aurora_record_exception_from_locals(
                                locals(),
                                module=__name__,
                                operation="exception_handler:aurora.py:9518",
                                exc=_aurora_boundary_exc,
                                context={"function": "_try_poedex_lookup", "handler_line": 9518, "source_file": "aurora.py"},
                            )
                            pass
                        try: _query_path.unlink(missing_ok=True)
                        except Exception as _aurora_boundary_exc:
                            _aurora_record_exception_from_locals(
                                locals(),
                                module=__name__,
                                operation="exception_handler:aurora.py:9520",
                                exc=_aurora_boundary_exc,
                                context={"function": "_try_poedex_lookup", "handler_line": 9520, "source_file": "aurora.py"},
                            )
                            pass
                        if _txt and len(_txt) > 20:
                            if use_researcher:
                                _digest_research_text(_txt, systems, source_text=topic, source="poedex")
                            return _txt
                        return ''
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:9522",
                        exc=_aurora_boundary_exc,
                        context={"function": "_try_poedex_lookup", "handler_line": 9522, "source_file": "aurora.py"},
                    )
                    pass

        # Timeout — remove the dangling query file
        try: _query_path.unlink(missing_ok=True)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9527",
                exc=_aurora_boundary_exc,
                context={"function": "_try_poedex_lookup", "handler_line": 9527, "source_file": "aurora.py"},
            )
            pass
        return ''
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9529",
            exc=_aurora_boundary_exc,
            context={"function": "_try_poedex_lookup", "handler_line": 9529, "source_file": "aurora.py"},
        )
        return ''


def _normalize_poedex_concept(value: str) -> str:
    concept = str(value or "").strip().lower()
    concept = re.sub(r"\s+", " ", concept)
    concept = concept.strip(" \t\r\n.,;:!?\"'()[]{}")
    return concept


def _queue_warp_poedex_study_target(
    systems: Dict[str, Any],
    concept: str,
    *,
    reason: str = "",
    priority: float = 0.88,
) -> bool:
    if not isinstance(systems, dict):
        return False
    concept_clean = _normalize_poedex_concept(concept)
    if not concept_clean:
        return False

    # If Aurora has already grounded this concept, do not keep re-queuing it.
    if _lookup_local_grounded_definition(concept_clean, systems):
        return False

    history = systems.setdefault("_warp_research_history", {})
    now = time.time()
    last_ts = float(history.get(concept_clean, 0.0) or 0.0)
    if last_ts and (now - last_ts) < 600.0:
        return False

    perception = systems.get("perception")
    oets = getattr(perception, "oets", None) if perception is not None else None
    research = getattr(oets, "research", None) if oets is not None else None
    if research is None:
        return False

    try:
        pending = any(
            str(getattr(req, "word", "") or "").strip().lower() == concept_clean
            and str(getattr(req, "reason", "") or "").strip() == "warp_shallow_seek"
            and str(getattr(req, "status", "") or "").strip().lower() == "pending"
            for req in getattr(research, "queue", []) or []
        )
        if pending:
            history[concept_clean] = now
            return False

        from aurora_internal.aurora_ontological_scaffolding import (
            ResearchRequest as _RR,
            _generate_id as _gid,
        )
        research.queue.insert(
            0,
            _RR(
                request_id=_gid("warp_seek"),
                word=concept_clean,
                priority=priority,
                reason="warp_shallow_seek",
            ),
        )
        history[concept_clean] = now
        systems["_warp_research_target"] = {
            "concept": concept_clean,
            "reason": str(reason or "").strip(),
            "queued_at": now,
            "priority": priority,
        }
        return True
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9601",
            exc=_aurora_boundary_exc,
            context={"function": "_queue_warp_poedex_study_target", "handler_line": 9601, "source_file": "aurora.py"},
        )
        return False


def _deposit_poedex_result_into_crystals(
    systems: Dict[str, Any],
    concept: str,
    learned_text: str,
    *,
    request_text: str = "",
    source: str = "poedex",
) -> None:
    if not isinstance(systems, dict):
        return
    concept_clean = _normalize_poedex_concept(concept)
    learned_clean = str(learned_text or "").strip()
    if not concept_clean or not learned_clean:
        return

    distilled = _compose_grounded_prefetch_response(concept_clean, learned_clean) or learned_clean[:400]

    # Single crystal write — everything goes into the DPS Crystal.
    # CCR and separate logs are not needed; the DPS Crystal IS the record.
    dim = systems.get("dimensional")
    dps = getattr(dim, "dps", None) if dim is not None else None
    if dps is not None:
        try:
            crystal = dps._get_or_create(f"concept:{concept_clean[:40]}")
            crystal.add_facet("poedex_understanding", distilled[:120], confidence=0.80)
            crystal.add_facet("poedex_source", source[:40], confidence=0.54)
            crystal.use()
            crystal.evolve()
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9633",
                exc=_aurora_boundary_exc,
                context={"function": "_deposit_poedex_result_into_crystals", "handler_line": 9633, "source_file": "aurora.py"},
            )
            pass

    # Sensory crystal novelty/recognition tracking only (no DPS re-write).
    sensory_crystal = systems.get("sensory_crystal")
    if sensory_crystal is not None:
        try:
            if hasattr(sensory_crystal, "observe_semantic"):
                sensory_crystal.observe_semantic(concept_clean, weight=1.0, source=source)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9642",
                exc=_aurora_boundary_exc,
                context={"function": "_deposit_poedex_result_into_crystals", "handler_line": 9642, "source_file": "aurora.py"},
            )
            pass

    # Deepen OETS immediately with the definition — knowledge is here now.
    try:
        _perc = systems.get("perception")
        _oets = getattr(_perc, "oets", None) if _perc is not None else None
        if _oets is not None and hasattr(_oets, "teach"):
            _oets.teach(concept_clean, distilled)
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9651",
            exc=_aurora_boundary_exc,
            context={"function": "_deposit_poedex_result_into_crystals", "handler_line": 9651, "source_file": "aurora.py"},
        )
        pass


def _broadcast_poedex_result(
    systems: Dict[str, Any],
    *,
    concept: str,
    request_text: str,
    result_text: str,
    source: str = "poedex_lookup",
    pipeline_state: Optional[Dict[str, Any]] = None,
    provisional: bool = False,
) -> Dict[str, Any]:
    concept_clean = str(concept or "").strip()
    request_clean = str(request_text or "").strip()
    result_clean = str(result_text or "").strip()
    if not result_clean or not isinstance(systems, dict):
        return {}

    packet = {
        "concept": concept_clean,
        "request": request_clean,
        "result": result_clean,
        "source": source,
        "status": "ready",
    }
    systems["_last_poedex_lookup"] = dict(packet)

    if isinstance(pipeline_state, dict):
        pipeline_state["poedex_lookup_concept"] = concept_clean
        pipeline_state["poedex_lookup_request"] = request_clean
        pipeline_state["poedex_lookup_result"] = result_clean
        pipeline_state["poedex_lookup_status"] = "ready"

    # Zip patch (generative-communication, 2026-08-02): a live research
    # result is evidence for the current turn, not automatically a durable
    # belief. Automatic gap repair uses the provisional path so the result
    # can be re-applied to the source utterance, reflected on, and then
    # promoted only after receiver evidence (Communication Credit
    # Unification). Explicit/manual lookup keeps the established
    # immediate-integration behavior below.
    if provisional:
        systems["_last_research_observation"] = {
            **packet,
            "provisional": True,
        }
        return packet

    conversation_memory = systems.get("conversation_memory")
    if conversation_memory is not None:
        try:
            if hasattr(conversation_memory, "learn_fact"):
                subject = concept_clean or request_clean or "poedex lookup"
                conversation_memory.learn_fact(
                    f"{subject}: {result_clean}",
                    source=source,
                    confidence=0.9,
                )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9695",
                exc=_aurora_boundary_exc,
                context={"function": "_broadcast_poedex_result", "handler_line": 9695, "source_file": "aurora.py"},
            )
            pass

    working_memory = systems.get("working_memory")
    if working_memory is not None:
        try:
            if hasattr(working_memory, "last_search_results"):
                working_memory.last_search_results = [{
                    "title": f"Poedex: {concept_clean or request_clean}",
                    "url": "",
                    "snippet": result_clean,
                    "source": source,
                }]
                working_memory.last_search_query = concept_clean or request_clean
            if hasattr(working_memory, "note_user_facts"):
                working_memory.note_user_facts(
                    f"{concept_clean or request_clean} = {result_clean}"
                )
            if hasattr(working_memory, "_register_semantic_frame"):
                try:
                    working_memory._register_semantic_frame({
                        "term": concept_clean or request_clean,
                        "summary": result_clean,
                        "source": source,
                        "confidence": 0.9,
                    })
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:9721",
                        exc=_aurora_boundary_exc,
                        context={"function": "_broadcast_poedex_result", "handler_line": 9721, "source_file": "aurora.py"},
                    )
                    pass
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9723",
                exc=_aurora_boundary_exc,
                context={"function": "_broadcast_poedex_result", "handler_line": 9723, "source_file": "aurora.py"},
            )
            pass

    understanding_contract = systems.get("understanding_contract")
    if understanding_contract is not None and hasattr(understanding_contract, "ingest_observation"):
        try:
            understanding_contract.ingest_observation(
                systems,
                request_clean or concept_clean or result_clean,
                understood={
                    "topic": concept_clean,
                    "search_result": result_clean,
                    "source": source,
                },
                turn_tick=int(getattr(working_memory, "turn_count", 0) or 0),
                source=source,
                session_id=str(systems.get("session_id") or ""),
            )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9741",
                exc=_aurora_boundary_exc,
                context={"function": "_broadcast_poedex_result", "handler_line": 9741, "source_file": "aurora.py"},
            )
            pass

    return packet


def _poedex_lookup_evidence(
    query: str,
    systems: Dict[str, Any],
    *,
    request_text: str = "",
    timeout: float = 2.0,
    use_researcher: bool = True,
    pipeline_state: Optional[Dict[str, Any]] = None,
    provisional: bool = False,
) -> List[Dict[str, Any]]:
    query_clean = str(query or "").strip()
    if not query_clean or not isinstance(systems, dict):
        return []
    result = str(
        _try_poedex_lookup(query_clean, systems, timeout=timeout, use_researcher=use_researcher) or ""
    ).strip()
    if not result:
        return []
    _broadcast_poedex_result(
        systems,
        concept=query_clean,
        request_text=request_text or query_clean,
        result_text=result,
        source="poedex_lookup",
        pipeline_state=pipeline_state,
        provisional=provisional,
    )
    return [{
        "title": f"Poedex: {query_clean}",
        "url": "",
        "snippet": result,
        "source": "poedex",
    }]


def _select_noncomp_anchor(
    text: str,
    understood: Optional[Dict[str, Any]] = None,
    pipeline_state: Optional[Dict[str, Any]] = None,
) -> str:
    understood = dict(understood or {})
    pipeline_state = dict(pipeline_state or {})
    vague_referents = {
        str(item).strip().lower()
        for item in getattr(WorkingMemory, "_VAGUE_REFERENTS", set()) or set()
        if str(item).strip()
    }
    candidates: List[str] = []
    for candidate in (
        understood.get("topic"),
        understood.get("search_query"),
        pipeline_state.get("noncomp_gap_anchor"),
        pipeline_state.get("concept_gap"),
        pipeline_state.get("resolved_referent_topic"),
        *(understood.get("topic_words", []) or []),
        *(understood.get("entities", []) or []),
    ):
        label = str(candidate or "").strip()
        if not label:
            continue
        low = label.lower()
        if low in vague_referents or len(low) < 2:
            continue
        if low not in {item.lower() for item in candidates}:
            candidates.append(label)
    if candidates:
        return candidates[0]

    cleaned = re.findall(r"[A-Za-z][A-Za-z0-9_+\-]{2,}", str(text or ""))
    for token in cleaned:
        if token.lower() not in vague_referents:
            return token
    return ""


def _sync_noncomp_runtime_band(systems: Dict[str, Any]) -> str:
    band_pos = "inside"
    try:
        bias_engine = systems.get("bias_engine")
        if bias_engine is not None:
            band_pos = str(getattr(bias_engine, "band_position", band_pos) or band_pos)
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:9826",
            exc=_aurora_boundary_exc,
            context={"function": "_sync_noncomp_runtime_band", "handler_line": 9826, "source_file": "aurora.py"},
        )
        band_pos = "inside"
    nudges = dict(systems.get("_last_bias_nudges") or {})
    router = systems.get("noncomp_manifold_router")
    if router is not None and hasattr(router, "update_band"):
        try:
            router.update_band(band_pos, nudges)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9833",
                exc=_aurora_boundary_exc,
                context={"function": "_sync_noncomp_runtime_band", "handler_line": 9833, "source_file": "aurora.py"},
            )
            pass
    interpreter = systems.get("noncomp_reflexive_interpreter")
    if interpreter is not None and hasattr(interpreter, "update_band"):
        try:
            interpreter.update_band(band_pos)
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9839",
                exc=_aurora_boundary_exc,
                context={"function": "_sync_noncomp_runtime_band", "handler_line": 9839, "source_file": "aurora.py"},
            )
            pass
    systems["noncomp_runtime_band"] = band_pos
    return band_pos


def _stage_noncomp_prefetch(
    systems: Dict[str, Any],
    pipeline_state: Optional[Dict[str, Any]],
    anchor: str,
) -> None:
    if not isinstance(pipeline_state, dict):
        return
    concept = str(anchor or "").strip()
    if not concept:
        return
    current_concept = str(pipeline_state.get("poedex_prefetch_concept", "") or "").strip()
    current_status = str(pipeline_state.get("poedex_prefetch_status", "") or "").strip().lower()
    if current_concept.lower() == concept.lower() and current_status in {"pending", "ready"}:
        return

    pipeline_state["poedex_prefetch_concept"] = concept
    pipeline_state["poedex_prefetch_status"] = "pending"
    pipeline_state.pop("poedex_prefetch_result", None)

    def _prefetch_worker() -> None:
        try:
            result = ""
            poedex_fn = systems.get("poedex") if isinstance(systems, dict) else None
            if poedex_fn is not None and callable(poedex_fn):
                try:
                    result = str(
                        poedex_fn(concept, cat="researcher", lane="self", timeout=12.0) or ""
                    ).strip()
                except TypeError as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:9873",
                        exc=_aurora_boundary_exc,
                        context={"function": "_prefetch_worker", "handler_line": 9873, "source_file": "aurora.py"},
                    )
                    result = str(poedex_fn(concept, cat="researcher", lane="self") or "").strip()
            else:
                result = str(
                    _try_poedex_lookup(concept, systems, timeout=2.0, use_researcher=True) or ""
                ).strip()
            if result:
                pipeline_state["poedex_prefetch_result"] = result
                pipeline_state["poedex_prefetch_status"] = "ready"
                try:
                    _broadcast_poedex_result(
                        systems,
                        concept=concept,
                        request_text=concept,
                        result_text=result,
                        source="poedex_prefetch",
                        pipeline_state=pipeline_state,
                    )
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:9891",
                        exc=_aurora_boundary_exc,
                        context={"function": "_prefetch_worker", "handler_line": 9891, "source_file": "aurora.py"},
                    )
                    pass
            else:
                pipeline_state["poedex_prefetch_status"] = "empty"
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9895",
                exc=_aurora_boundary_exc,
                context={"function": "_prefetch_worker", "handler_line": 9895, "source_file": "aurora.py"},
            )
            pipeline_state["poedex_prefetch_status"] = "error"

    threading.Thread(
        target=_prefetch_worker,
        name=f"aurora-noncomp-prefetch:{concept[:24]}",
        daemon=True,
    ).start()


def _apply_poedex_learning_result(
    systems: Dict[str, Any],
    concept: str,
    request_text: str,
    result_text: str,
    *,
    source_text: str = "",
) -> Dict[str, Any]:
    concept_clean = str(concept or "").strip().lower()
    request_clean = str(request_text or "").strip()
    result_clean = str(result_text or "").strip()
    if not result_clean or not isinstance(systems, dict):
        return {}

    learning_note = _compose_grounded_prefetch_response(concept_clean, result_clean)
    if not learning_note:
        first_sentence = re.split(r"(?<=[.!?])\s+", result_clean, maxsplit=1)[0].strip()
        learning_note = first_sentence or result_clean
    if concept_clean and learning_note and concept_clean not in learning_note.lower():
        learning_note = f"{concept_clean} learns: {learning_note}"

    applied: Dict[str, Any] = {
        "concept": concept_clean,
        "request": request_clean,
        "result": result_clean,
        "learning_note": learning_note,
        "applied": False,
        "source": "poedex_learning",
    }

    working_memory = systems.get("working_memory")
    if working_memory is not None:
        try:
            grounded = _meaning_text_is_grounded(result_clean, term=concept_clean) if concept_clean else False
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:9939",
                exc=_aurora_boundary_exc,
                context={"function": "_apply_poedex_learning_result", "handler_line": 9939, "source_file": "aurora.py"},
            )
            grounded = False

        if grounded and concept_clean:
            learned = _apply_word_meaning_learning(
                concept_clean,
                result_clean,
                systems,
                source_text=source_text or request_clean,
                source="poedex_learning",
            )
            if learned.get("definition"):
                applied["applied"] = True
                applied["definition"] = str(learned.get("definition", "") or "").strip()
                applied["systems_updated"] = list(learned.get("systems_updated", []) or [])
                _deposit_poedex_result_into_crystals(
                    systems,
                    concept_clean,
                    learning_note,
                    request_text=source_text or request_clean,
                    source="poedex_learning",
                )
                _queue_poedex_representation_followup(
                    systems,
                    concept_clean,
                    source_text=source_text or request_clean,
                    reason="poedex_learning_result",
                )
                return applied

        try:
            if hasattr(working_memory, "concept_meanings"):
                term_key = re.sub(
                    r"\s+",
                    " ",
                    re.sub(
                        r"[^a-z0-9]+",
                        " ",
                        f"poedex learning {concept_clean or 'material'}".lower(),
                    ),
                ).strip()
                profile = _meaning_profile_for_value(learning_note)
                concept_entry = {
                    "term": term_key,
                    "meaning": learning_note,
                    "contrast": "",
                    "source": "poedex_learning",
                    "turn": int(getattr(working_memory, "turn_count", 0) or 0),
                    "text": request_clean or learning_note,
                    "summary": learning_note,
                    "confidence": 0.7,
                    "verification_needed": not bool(concept_clean),
                    "anchor_mode": "poedex_learning",
                    "meaning_profile": dict(profile),
                    "meaning_signature": str(profile.get("signature", "") or ""),
                    "meaning_axes": tuple(profile.get("axes", ()) or ()),
                    "meaning_stage": str(profile.get("stage", "") or ""),
                    "meaning_representation": str(profile.get("representation", "") or ""),
                }
                working_memory.concept_meanings[term_key] = dict(concept_entry)
                working_memory.pending_concept_clarification = dict(concept_entry)
                working_memory.last_concept_anchor = term_key
                if term_key not in working_memory.stated_facts:
                    working_memory.stated_facts[term_key] = {}
                working_memory.stated_facts[term_key]["meaning"] = learning_note
                if hasattr(working_memory, "_register_mention"):
                    working_memory._register_mention(term_key, "concept", "poedex_learning", 0.88)
                if hasattr(working_memory, "_register_semantic_frame") and hasattr(working_memory, "_semantic_frame_from_concept"):
                    try:
                        working_memory._register_semantic_frame(
                            working_memory._semantic_frame_from_concept(concept_entry)
                        )
                    except Exception as _aurora_boundary_exc:
                        _aurora_record_exception_from_locals(
                            locals(),
                            module=__name__,
                            operation="exception_handler:aurora.py:10011",
                            exc=_aurora_boundary_exc,
                            context={"function": "_apply_poedex_learning_result", "handler_line": 10011, "source_file": "aurora.py"},
                        )
                        pass
                applied["applied"] = True
                applied["systems_updated"] = ["working_memory.concept_meanings", "working_memory.stated_facts"]
                _deposit_poedex_result_into_crystals(
                    systems,
                    concept_clean,
                    learning_note,
                    request_text=source_text or request_clean,
                    source="poedex_learning",
                )
                _queue_poedex_representation_followup(
                    systems,
                    concept_clean,
                    source_text=source_text or request_clean,
                    reason="poedex_learning_result",
                )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:10028",
                exc=_aurora_boundary_exc,
                context={"function": "_apply_poedex_learning_result", "handler_line": 10028, "source_file": "aurora.py"},
            )
            pass

    try:
        _deposit_poedex_result_into_crystals(
            systems,
            concept_clean or request_clean,
            learning_note,
            request_text=source_text or request_clean,
            source="poedex_learning",
        )
        _broadcast_poedex_result(
            systems,
            concept=concept_clean or request_clean,
            request_text=request_clean or source_text,
            result_text=result_clean,
            source="poedex_learning",
        )
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:10046",
            exc=_aurora_boundary_exc,
            context={"function": "_apply_poedex_learning_result", "handler_line": 10046, "source_file": "aurora.py"},
        )
        pass

    return applied


def _apply_poedex_representation_result(
    systems: Dict[str, Any],
    concept: str,
    request_text: str,
    result_text: str,
    *,
    source_text: str = "",
) -> Dict[str, Any]:
    concept_clean = str(concept or "").strip().lower()
    request_clean = str(request_text or "").strip()
    result_clean = str(result_text or "").strip()
    if not result_clean or not isinstance(systems, dict):
        return {}

    working_memory = systems.get("working_memory")
    if working_memory is None or not hasattr(working_memory, "concept_meanings"):
        return {}

    variants: List[str] = []
    for chunk in re.split(r"[\n;]+", result_clean):
        piece = re.sub(r"\s+", " ", chunk).strip(" -•\t")
        if piece and piece not in variants:
            variants.append(piece)
    if not variants:
        variants = [result_clean]

    term_key = re.sub(
        r"\s+",
        " ",
        re.sub(
            r"[^a-z0-9]+",
            " ",
            f"poedex representation {concept_clean or 'material'}".lower(),
        ),
    ).strip()
    profile = _meaning_profile_for_value(" ".join(variants[:2]) or concept_clean)
    entry = dict(working_memory.concept_meanings.get(concept_clean, {}) or {})
    if not entry:
        entry = {
            "term": concept_clean or term_key,
            "meaning": concept_clean or term_key,
            "contrast": "",
            "source": "poedex_representation",
            "turn": int(getattr(working_memory, "turn_count", 0) or 0),
            "text": request_clean[:280],
            "summary": request_clean[:280],
            "confidence": 0.72,
            "verification_needed": False,
            "anchor_mode": "poedex_representation",
        }
    entry["representation_variants"] = variants
    entry["representation_source"] = "poedex_representation"
    entry["representation_request"] = request_clean
    entry["representation_note"] = variants[0]
    entry["meaning_profile"] = dict(profile)
    entry["meaning_signature"] = str(profile.get("signature", "") or entry.get("meaning_signature", "") or "")
    entry["meaning_axes"] = tuple(profile.get("axes", ()) or entry.get("meaning_axes", ()) or ())
    entry["meaning_stage"] = str(profile.get("stage", "") or entry.get("meaning_stage", "") or "")
    entry["meaning_representation"] = str(profile.get("representation", "") or entry.get("meaning_representation", "") or "")
    working_memory.concept_meanings[concept_clean or term_key] = dict(entry)
    if hasattr(working_memory, "pending_concept_clarification"):
        working_memory.pending_concept_clarification = dict(entry)
    if hasattr(working_memory, "last_concept_anchor"):
        working_memory.last_concept_anchor = concept_clean or term_key
    if concept_clean not in working_memory.stated_facts:
        working_memory.stated_facts[concept_clean or term_key] = {}
    working_memory.stated_facts[concept_clean or term_key]["representation"] = variants[0][:280]
    try:
        if hasattr(working_memory, "_register_semantic_frame") and hasattr(working_memory, "_semantic_frame_from_concept"):
            working_memory._register_semantic_frame(
                working_memory._semantic_frame_from_concept(entry)
            )
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:10124",
            exc=_aurora_boundary_exc,
            context={"function": "_apply_poedex_representation_result", "handler_line": 10124, "source_file": "aurora.py"},
        )
        pass
    try:
        if hasattr(working_memory, "_register_mention"):
            working_memory._register_mention(concept_clean or term_key, "concept", "poedex_representation", 0.88)
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:10129",
            exc=_aurora_boundary_exc,
            context={"function": "_apply_poedex_representation_result", "handler_line": 10129, "source_file": "aurora.py"},
        )
        pass
    systems["_poedex_representation"] = {
        "concept": concept_clean or term_key,
        "request": request_clean,
        "result": result_clean,
        "variants": variants,
        "source": "poedex_representation",
    }
    try:
        _broadcast_poedex_result(
            systems,
            concept=concept_clean or term_key,
            request_text=request_clean or source_text,
            result_text=result_clean,
            source="poedex_representation",
        )
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:10146",
            exc=_aurora_boundary_exc,
            context={"function": "_apply_poedex_representation_result", "handler_line": 10146, "source_file": "aurora.py"},
        )
        pass
    _deposit_poedex_result_into_crystals(
        systems,
        concept_clean or term_key,
        entry.get("meaning_representation", "") or variants[0],
        request_text=source_text or request_clean,
        source="poedex_representation",
    )
    return {
        "concept": concept_clean or term_key,
        "request": request_clean,
        "result": result_clean,
        "variants": variants,
        "systems_updated": ["working_memory.concept_meanings", "working_memory.stated_facts"],
        "source": "poedex_representation",
    }


def _stage_poedex_learning_request(
    systems: Dict[str, Any],
    pipeline_state: Optional[Dict[str, Any]],
    anchor: str,
    *,
    source_text: str = "",
    reason: str = "",
) -> None:
    if not isinstance(pipeline_state, dict):
        return
    concept = str(anchor or "").strip()
    if not concept:
        return
    if _lookup_local_grounded_definition(concept, systems):
        return
    current_concept = str(pipeline_state.get("poedex_learning_concept", "") or "").strip()
    current_status = str(pipeline_state.get("poedex_learning_status", "") or "").strip().lower()
    if current_concept.lower() == concept.lower() and current_status in {"pending", "ready"}:
        return

    request_text = f"What new material should Aurora learn about {concept}?"
    pipeline_state["poedex_learning_concept"] = concept
    pipeline_state["poedex_learning_request"] = request_text
    pipeline_state["poedex_learning_reason"] = str(reason or "").strip()
    pipeline_state["poedex_learning_status"] = "pending"
    pipeline_state.pop("poedex_learning_result", None)
    _queue_warp_poedex_study_target(systems, concept, reason=reason)

    def _learning_worker() -> None:
        try:
            result = ""
            poedex_fn = systems.get("poedex") if isinstance(systems, dict) else None
            if poedex_fn is not None and callable(poedex_fn):
                try:
                    result = str(
                        poedex_fn(request_text, cat="researcher", lane="self", timeout=12.0) or ""
                    ).strip()
                except TypeError as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:10202",
                        exc=_aurora_boundary_exc,
                        context={"function": "_learning_worker", "handler_line": 10202, "source_file": "aurora.py"},
                    )
                    result = str(poedex_fn(request_text, cat="researcher", lane="self") or "").strip()
            if not result:
                result = str(
                    _try_poedex_lookup(concept, systems, timeout=2.0, use_researcher=True) or ""
                ).strip()
            if result:
                applied = _apply_poedex_learning_result(
                    systems,
                    concept,
                    request_text,
                    result,
                    source_text=source_text or request_text,
                )
                payload = {
                    "concept": concept,
                    "request": request_text,
                    "result": result,
                    "note": str(applied.get("learning_note", "") or ""),
                    "status": "ready",
                    "applied": bool(applied.get("applied", False)),
                    "reason": str(reason or "").strip(),
                }
                pipeline_state["poedex_learning_result"] = payload["result"]
                pipeline_state["poedex_learning_status"] = "ready"
                if payload["note"]:
                    pipeline_state["poedex_learning_note"] = payload["note"]
                pipeline_state["poedex_learning_applied"] = bool(payload["applied"])
                if isinstance(systems, dict):
                    systems["_poedex_learning"] = dict(payload)
            else:
                pipeline_state["poedex_learning_status"] = "empty"
                if isinstance(systems, dict):
                    systems["_poedex_learning"] = {
                        "concept": concept,
                        "request": request_text,
                        "result": "",
                        "status": "empty",
                        "reason": str(reason or "").strip(),
                    }
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:10242",
                exc=_aurora_boundary_exc,
                context={"function": "_learning_worker", "handler_line": 10242, "source_file": "aurora.py"},
            )
            pipeline_state["poedex_learning_status"] = "error"
            if isinstance(systems, dict):
                systems["_poedex_learning"] = {
                    "concept": concept,
                    "request": request_text,
                    "result": "",
                    "status": "error",
                    "reason": str(reason or "").strip(),
                }

    threading.Thread(
        target=_learning_worker,
        name=f"aurora-poedex-learning:{concept[:24]}",
        daemon=True,
    ).start()


