def _update_ivm_from_epoch(
    systems: Dict[str, Any],
    epoch_result: Dict[str, Any],
    failpoint_update: Dict[str, Any],
) -> None:
    """
    Bridge training outcomes to IVM axis state.

    Uses direct phase-setting (EMA blend per epoch) rather than inject_stimulus.
    IVM axes boot at phase=0.0 (polarity=1.0 max positive). Velocity injections
    barely move the phase from that starting point; directly targeting the correct
    phase lets axes converge to an honest reflection of training scores within a
    few epochs.

    score [0, 1] → target_polarity = score*2 - 1 → target_phase = acos(target_polarity)
    new_phase = current_phase + α*(target_phase - current_phase)   [α = 0.35/epoch]

    At fitness=0.25 this gives:  polarity≈-0.50 → normalized ≈ 0.25 (honest failure)
    At fitness=0.80 this gives:  polarity≈+0.60 → normalized ≈ 0.80 (honest progress)
    """
    lattice = systems.get('lattice')
    if lattice is None or not hasattr(lattice, 'vertices'):
        return

    # Map training dimensions to IVM long-name axes
    _DIM_TO_AXIS: Dict[str, str] = {
        'contradiction_handling':      'existence',
        'self_expression':             'existence',
        'context_carryover':           'temporal',
        'multi_turn_stability':        'temporal',
        'semantic_precision':          'energy',
        'coherence_maintenance':       'boundary',
        'uncertainty_signaling':       'boundary',
        'relational_depth':            'boundary',
        'adaptive_strategy_selection': 'agency',
        'perspective_integration':     'agency',
    }

    # Accumulate per-axis score samples
    axis_scores: Dict[str, List[float]] = {}

    fitness = float(epoch_result.get('avg_fitness', 0.5) or 0.5)
    axis_scores.setdefault('existence', []).append(fitness)

    for dim, score in (failpoint_update.get('weakest_dimensions') or []):
        ax = _DIM_TO_AXIS.get(dim)
        if ax is not None:
            axis_scores.setdefault(ax, []).append(float(score or 0.0))

    # Seed axes with no dimension-specific data from overall fitness so they
    # don't stay permanently at boot-time 1.0 (phase=0.0). Uses half the EMA
    # weight so dimension scores dominate when present.
    _ALL_AXES = ('existence', 'temporal', 'energy', 'boundary', 'agency')
    for ax_long in _ALL_AXES:
        if ax_long not in axis_scores:
            axis_scores[ax_long] = [fitness]

    _ALPHA = 0.35   # EMA convergence rate per epoch
    try:
        axes = lattice.vertices.axes
        for ax_long, scores in axis_scores.items():
            if ax_long not in axes:
                continue
            avg_score = sum(scores) / len(scores)
            # score [0,1] → polarity [-1,+1]; clamp away from ±1 (acos undefined)
            target_polarity = max(-0.995, min(0.995, avg_score * 2.0 - 1.0))
            target_phase = math.acos(target_polarity)
            current_phase = float(getattr(axes[ax_long], 'phase', 0.0))
            axes[ax_long].phase = current_phase + _ALPHA * (target_phase - current_phase)
            # Zero velocity — phase moved directly, no residual drift
            if hasattr(axes[ax_long], 'angular_velocity'):
                axes[ax_long].angular_velocity = 0.0

        # Refresh polarity cache so get_global_polarity() returns updated values
        if hasattr(lattice, 'compute_global_polarity'):
            lattice.compute_global_polarity()
        elif hasattr(lattice, 'vertices') and hasattr(lattice.vertices, 'compute_global_polarity'):
            lattice.vertices.compute_global_polarity()
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:21973",
            exc=_aurora_boundary_exc,
            context={"function": "_update_ivm_from_epoch", "handler_line": 21973, "source_file": "aurora.py"},
        )
        pass


# Shared concept mapping for OETS seeding and seek simulation.
# Keys = training dimension names. Values = concept words seeded into / sought from OETS web.
_DIM_CONCEPTS_MAP: Dict[str, List[str]] = {
    'contradiction_handling':      ['contradiction', 'existence_clarity', 'consistency'],
    'context_carryover':           ['continuity', 'context', 'carryover'],
    'coherence_maintenance':       ['coherence', 'boundary_clarity', 'structure'],
    'adaptive_strategy_selection': ['adaptation', 'strategy', 'flexibility'],
    'semantic_precision':          ['precision', 'clarity', 'meaning'],
    'perspective_integration':     ['perspective', 'integration', 'viewpoint'],
    'multi_turn_stability':        ['stability', 'continuity', 'consistency'],
    'uncertainty_signaling':       ['uncertainty', 'boundary', 'signal'],
    'relational_depth':            ['relation', 'depth', 'connection'],
    'self_expression':             ['expression', 'self', 'voice'],
}


def _simulate_training_seek(
    systems: Dict[str, Any],
    failpoint_update: Dict[str, Any],
) -> None:
    """
    Simulate WARP-SEEK for each weakest training dimension.

    In live conversation, SEEK fires whenever Aurora can't resolve something
    from internal knowledge. Training never triggers this path. Calling this
    BEFORE _seed_oets_from_failpoints means seeks test concepts seeded by
    previous epochs — internal% grows as OETS accumulates knowledge across
    epochs, creating the compounding effect.

    Epoch N:   seek tests prior-epoch nodes  → some internal hits
    Epoch N+1: seek finds more seeded nodes  → internal% rises
    """
    try:
        perc = systems.get('perception')
        oets = getattr(perc, 'oets', None) if perc else None
        web  = getattr(oets, 'web', None) if oets else None
        if web is None or not hasattr(web, 'has_node'):
            return

        tc = systems.get('_seek_stats')
        if tc is None:
            return

        for dim, score in (failpoint_update.get('weakest_dimensions') or []):
            if float(score or 0.0) > 0.55:
                continue   # only seek for genuinely failing dimensions

            concepts = _DIM_CONCEPTS_MAP.get(dim, [dim[:32]])
            if any(web.has_node(c) for c in concepts):
                tc['internal'] = tc.get('internal', 0) + 1
            else:
                tc['external'] = tc.get('external', 0) + 1
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:22029",
            exc=_aurora_boundary_exc,
            context={"function": "_simulate_training_seek", "handler_line": 22029, "source_file": "aurora.py"},
        )
        pass


def _run_training_constraint_pass(
    systems: Dict[str, Any],
    epoch_result: Dict[str, Any],
    failpoint_update: Dict[str, Any],
) -> None:
    """
    Run constraint reasoning on the current (now-honest) IVM state after
    each training epoch.

    In live conversation, begin_response_turn() calls cr.reason() then
    cr.integrate() which builds the pattern ledger and enables DPS
    crystallization. Training never calls this path. This pass closes
    the loop so crystallization can happen during training as well.

    The semantic state proxy is built from per-dimension training scores
    mapped to their axis. This makes alignment measure "does the constraint
    reasoning predict the same axis state the training scores show?" —
    the correct question. High alignment means constraint reasoning is
    structurally coherent with what Aurora is actually experiencing.
    """
    cr = systems.get('constraint_reasoner')
    if cr is None:
        return
    try:
        profile = cr.current_profile()
        if profile is None:
            return

        # Build semantic proxy from training dimension scores (same axis mapping
        # as _update_ivm_from_epoch). Falls back to flat fitness for axes without data.
        fitness = float(epoch_result.get('avg_fitness', 0.5) or 0.5)
        _DIM_TO_AXIS_SHORT: Dict[str, str] = {
            'contradiction_handling':      'X',
            'self_expression':             'X',
            'context_carryover':           'T',
            'multi_turn_stability':        'T',
            'semantic_precision':          'N',
            'coherence_maintenance':       'B',
            'uncertainty_signaling':       'B',
            'relational_depth':            'B',
            'adaptive_strategy_selection': 'A',
            'perspective_integration':     'A',
        }
        axis_sums: Dict[str, List[float]] = {ax: [fitness] for ax in ('X', 'T', 'N', 'B', 'A')}
        axis_sums['X'] = [fitness]
        for dim, score in (failpoint_update.get('weakest_dimensions') or []):
            ax = _DIM_TO_AXIS_SHORT.get(dim)
            if ax is not None:
                axis_sums[ax].append(float(score or 0.0))
        semantic_proxy = {
            ax: round(sum(vals) / len(vals), 3)
            for ax, vals in axis_sums.items()
        }

        # Run 3 reasoning cycles on the stable post-IVM profile. The same profile
        # produces the same domain/narrative key in each cycle. Three consecutive
        # high-alignment verifications on a stable state meet the crystallization
        # threshold in one epoch — equivalent to 3 turns in a live conversation
        # all confirming the same structural pattern.
        for _ in range(3):
            trace = cr.reason(profile, depth=3)
            cr.integrate(trace, semantic_proxy, emit_warp=False)
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:22095",
            exc=_aurora_boundary_exc,
            context={"function": "_run_training_constraint_pass", "handler_line": 22095, "source_file": "aurora.py"},
        )
        pass


def _seed_oets_from_failpoints(
    systems: Dict[str, Any],
    failpoint_update: Dict[str, Any],
) -> None:
    """
    Seed failing-dimension concepts into the OETS relational web.

    When Aurora consistently fails context_carryover, she needs to have
    'continuity' and 'context' in her relational web so she can build
    understanding of those concepts from her existing knowledge base.
    Without seeding, seeks for these concepts always go external and
    never compound internally.
    """
    try:
        perc = systems.get('perception')
        oets = getattr(perc, 'oets', None) if perc else None
        web  = getattr(oets, 'web', None) if oets else None
        if web is None or not hasattr(web, 'add_node'):
            return
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:22118",
            exc=_aurora_boundary_exc,
            context={"function": "_seed_oets_from_failpoints", "handler_line": 22118, "source_file": "aurora.py"},
        )
        return

    for dim, score in (failpoint_update.get('weakest_dimensions') or []):
        score = float(score or 0)
        valence = round((score - 0.5) * 2.0, 3)   # -1.0 (complete fail) → +1.0 (mastered)
        for concept in _DIM_CONCEPTS_MAP.get(dim, [dim[:32]]):
            try:
                web.add_node(concept[:40], role="training_gap", valence=valence)
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22127",
                    exc=_aurora_boundary_exc,
                    context={"function": "_seed_oets_from_failpoints", "handler_line": 22127, "source_file": "aurora.py"},
                )
                pass


def train(systems: Dict[str, Any], epochs: int = 10,
          episodes_per_epoch: int = 8,
          turns_per_episode: int = 5,
          verbose: bool = True,
          phase_prefix: str = 'train'):
    """
    Run simulation training epochs to evolve Aurora's expression.
    This is how she learns to speak before you talk to her.
    """
    aurora = systems['aurora']
    perception = systems['perception']
    identity = systems['identity']
    ExistenceMode = systems['ExistenceMode']

    # ── Temporary dev telemetry ───────────────────────────────────────────────
    _dev_telem = None
    try:
        from aurora_dev_telemetry import DevTelemetry as _DevTelemetry
        _dev_telem = _DevTelemetry(systems)
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:22150",
            exc=_aurora_boundary_exc,
            context={"function": "train", "handler_line": 22150, "source_file": "aurora.py"},
        )
        pass
    # ─────────────────────────────────────────────────────────────────────────

    if verbose:
        print(f"  [TRAIN] Running {epochs} epochs ({episodes_per_epoch} episodes each)")
        print(f"  [TRAIN] Pre-training vocab: {perception.lexicon.size}")
        print(f"  [TRAIN] Pre-training DNA gen: {identity.dna.generation}")
        print()

    for epoch in range(epochs):
        phase_name = f"{phase_prefix}_epoch_{epoch + 1}"
        # Re-evaluate deferred WARP demands — decayed severity may now route
        # differently; anything still above noise floor gets re-classified.
        _wf_epoch = systems.get('warp_field')
        if _wf_epoch is not None:
            try:
                _wf_epoch.flush_deferred()
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22168",
                    exc=_aurora_boundary_exc,
                    context={"function": "train", "handler_line": 22168, "source_file": "aurora.py"},
                )
                pass
        dream_trainer = systems.get('dream_trainer')
        queued_lesson_specs = 0
        if dream_trainer is not None and hasattr(dream_trainer, 'flush_lessons_to_simulation'):
            try:
                queued_lesson_specs = int(
                    dream_trainer.flush_lessons_to_simulation(systems, force=True) or 0
                )
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22177",
                    exc=_aurora_boundary_exc,
                    context={"function": "train", "handler_line": 22177, "source_file": "aurora.py"},
                )
                queued_lesson_specs = 0
        plan = _build_response_pressure_training_plan(
            systems,
            phase=phase_name,
        )
        epoch_episodes = episodes_per_epoch + int(plan.get('episodes_bonus', 0) or 0)
        epoch_turns = turns_per_episode + int(plan.get('turns_bonus', 0) or 0)
        queued_specs = _apply_response_pressure_training_plan(
            systems,
            plan,
            episode_budget=epoch_episodes,
        )
        session = aurora.gateway.simulation.session
        episode_start = len(getattr(session, 'episodes', []) or [])
        result = aurora.gateway.simulation.run_epoch(
            episodes_per_epoch=epoch_episodes,
            turns_per_episode=epoch_turns,
            mode=ExistenceMode.AGENTIC,
        )
        new_episode_results = list(getattr(session, 'episodes', []) or [])[episode_start:]
        failpoint_update = _record_training_epoch_fail_points(
            systems,
            new_episode_results,
            phase_name=phase_name,
        )
        result['response_pressure_plan'] = dict(plan or {})
        result['response_pressure_specs'] = int(queued_specs or 0)
        result['dream_lesson_specs'] = int(queued_lesson_specs or 0)
        result['failpoint_update'] = dict(failpoint_update or {})

        # Bridge: push epoch scores into IVM axis state, then simulate the
        # live-conversation paths that training skips.
        # Order matters:
        #   1. IVM update first — constraint reasoning needs honest axis state
        #   2. Seek simulation BEFORE seeding — tests concepts from prior epochs
        #   3. Constraint pass — builds pattern ledger, enables DPS crystallization
        #   4. Seed OETS last — new concepts available for next epoch's seeks
        _update_ivm_from_epoch(systems, result, failpoint_update)
        _simulate_training_seek(systems, failpoint_update)
        _run_training_constraint_pass(systems, result, failpoint_update)
        _seed_oets_from_failpoints(systems, failpoint_update)
        quasiarch = systems.get('quasiarch_observer')
        if quasiarch is not None and hasattr(quasiarch, 'record_training_epoch'):
            try:
                result['quasiarch_event'] = quasiarch.record_training_epoch(
                    plan,
                    result,
                    phase=phase_name,
                )
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22227",
                    exc=_aurora_boundary_exc,
                    context={"function": "train", "handler_line": 22227, "source_file": "aurora.py"},
                )
                pass
        if dream_trainer is not None and hasattr(dream_trainer, 'retain_learner_state'):
            try:
                result['retained_learnings'] = int(
                    dream_trainer.retain_learner_state(systems, source=phase_name) or 0
                )
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22234",
                    exc=_aurora_boundary_exc,
                    context={"function": "train", "handler_line": 22234, "source_file": "aurora.py"},
                )
                result['retained_learnings'] = 0
        try:
            result['lineage_emergence'] = _observe_live_lineage_emergence(
                systems,
                source=phase_name,
            )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:22241",
                exc=_aurora_boundary_exc,
                context={"function": "train", "handler_line": 22241, "source_file": "aurora.py"},
            )
            result['lineage_emergence'] = []
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:22243",
                exc=_aurora_boundary_exc,
                context={"function": "train", "handler_line": 22243, "source_file": "aurora.py"},
            )
            result['social_api_reward'] = {}

        # Record telemetry snapshot for this epoch
        if _dev_telem is not None:
            try:
                _dev_telem.record(epoch + 1, result)
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:22250",
                    exc=_aurora_boundary_exc,
                    context={"function": "train", "handler_line": 22250, "source_file": "aurora.py"},
                )
                pass

        if verbose:
            fitness = result.get('avg_fitness', 0)
            shards = result.get('learner_shards', 0)
            gov = result.get('governor', {})
            dilation = gov.get('dilation', 0)
            state = gov.get('state', '?')

            bar = "#" * int(fitness * 20) + "." * (20 - int(fitness * 20))
            print(f"  Epoch {epoch+1:3d}/{epochs}  "
                  f"fitness=[{bar}] {fitness:.3f}  "
                  f"shards={shards:3d}  "
                  f"dilation={dilation:,.0f}x  "
                  f"state={state}")
            if plan.get('pressure_targets'):
                targets = ', '.join(
                    f"{dim}:{val:.2f}" for dim, val in list(plan['pressure_targets'].items())[:3]
                )
                print(f"           response_pressure={targets}  "
                      f"queued_specs={queued_specs}  "
                      f"turns={epoch_turns}")
            if queued_lesson_specs:
                print(f"           fail_lessons={queued_lesson_specs}  "
                      f"retained={result.get('retained_learnings', 0)}")
            if failpoint_update.get('scored_conversations'):
                weakest = ', '.join(
                    f"{dim}:{val:.2f}"
                    for dim, val in list(failpoint_update.get('weakest_dimensions', []))[:3]
                ) or "—"
                print(f"           failpoints=scored:{failpoint_update.get('scored_conversations', 0)}  "
                      f"recorded:{failpoint_update.get('recorded_failures', 0)}  "
                      f"weakest={weakest}")
            if result.get('lineage_emergence'):
                print(f"           lineage_new={len(list(result.get('lineage_emergence', []) or []))}")
            social_reward = dict(result.get('social_api_reward', {}) or {})
            if social_reward.get('awarded'):
                print(
                    f"           social_api_reward=+{float(social_reward.get('added_minutes', 0.0) or 0.0):.1f}m  "
                    f"time_left={float(social_reward.get('time_remaining_minutes', 0.0) or 0.0):.1f}m"
                )

    # Print telemetry diagnostic report
    if _dev_telem is not None:
        try:
            print(_dev_telem.report())
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:22297",
                exc=_aurora_boundary_exc,
                context={"function": "train", "handler_line": 22297, "source_file": "aurora.py"},
            )
            pass

    if verbose:
        print()
        print(f"  [TRAIN] Post-training vocab: {perception.lexicon.size}")
        print(f"  [TRAIN] Post-training DNA gen: {identity.dna.generation}")
        learned = aurora.gateway.simulation.session.learner.what_have_i_learned()
        if learned:
            print(f"  [TRAIN] What Aurora learned:")
            for l in learned[:5]:
                print(f"          * {l}")
        print()

    # Save state after training
    _full_save(systems, verbose=verbose)


# ============================================================================
# INTERNET CONNECTOR  Feed External Data Through the Gateway
# ============================================================================

def fetch_and_feed(systems: Dict[str, Any], url: str, verbose: bool = True):
    """
    Fetch a web page and feed its content to Aurora through the N-Space Gateway.
    Everything passes through L0 validation  L3 moral filter  L4 synthesis.
    """
    aurora = systems['aurora']
    StreamType = systems['StreamType']
    ExistenceMode = systems['ExistenceMode']

    if verbose:
        print(f"  [FEED] Fetching: {url}")

    try:
        import urllib.request
        import urllib.error
        req = urllib.request.Request(url, headers={
            'User-Agent': 'Aurora/2.0 Consciousness Architecture'
        })
        with urllib.request.urlopen(req, timeout=15) as response:
            raw = response.read().decode('utf-8', errors='replace')

        # Strip HTML tags (basic)
        import re
        text = re.sub(r'<[^>]+>', ' ', raw)
        text = re.sub(r'\s+', ' ', text).strip()

        # Truncate to reasonable size
        if len(text) > 5000:
            text = text[:5000] + "..."

        if verbose:
            print(f"  [FEED] Fetched {len(text)} chars")
            print(f"  [FEED] Routing through N-Space Gateway...")

        # Feed through Gateway  full pipeline
        resp = aurora.gateway.receive(
            content=text,
            stream_type=StreamType.KNOWLEDGE_FEED,
            source=url,
            mode=ExistenceMode.BOUNDED,
        )

        if verbose:
            stats = aurora.gateway.get_stats()
            print(f"  [FEED] Verdict: accepted={stats['total_accepted']} "
                  f"rejected={stats['total_rejected']} "
                  f"filtered={stats['total_filtered']}")
            print(f"  [FEED] Aurora's response: {resp.content}")
            print()

        return resp

    except Exception as e:
        if verbose:
            print(f"  [FEED] Error: {e}")
            print(f"  [FEED] Note: Internet access requires network connectivity.")
            print(f"         You can also feed text directly with --text 'content here'")
        return None


def feed_text(systems: Dict[str, Any], text: str, source: str = "direct_input",
              verbose: bool = True):
    """Feed raw text directly to Aurora through the Gateway."""
    aurora = systems['aurora']
    StreamType = systems['StreamType']
    ExistenceMode = systems['ExistenceMode']

    if verbose:
        print(f"  [FEED] Injecting {len(text)} chars from '{source}'")

    resp = aurora.gateway.receive(
        content=text,
        stream_type=StreamType.KNOWLEDGE_FEED,
        source=source,
        mode=ExistenceMode.BOUNDED,
    )

    if verbose:
        print(f"  [FEED] Aurora: {resp.content}")
    return resp


# ============================================================================
# AUTONOMOUS EXPLORATION
# ============================================================================

def explore(systems: Dict[str, Any], cycles: int = 10, verbose: bool = True):
    """
    Run autonomous exploration. Aurora processes quarantined data
    and probes unknown territories through simulation.
    """
    aurora = systems['aurora']
    ExistenceMode = systems['ExistenceMode']

    if verbose:
        print(f"  [EXPLORE] Starting autonomous exploration ({cycles} cycles)")
        print()

    for cycle in range(cycles):
        result = aurora.explore(cycles=3, mode=ExistenceMode.BOUNDED)
        if verbose:
            results = result.get('results', [])
            episodes = sum(r.get('epoch', 1) for r in results)
            quarantine = result.get('quarantine_remaining', 0)
            avg_fit = (sum(r.get('avg_fitness', r.get('fitness', 0))
                          for r in results) / max(1, len(results)))
            print(f"  Cycle {cycle+1:3d}/{cycles}  "
                  f"episodes={len(results)}  fit={avg_fit:.3f}  "
                  f"quarantine={quarantine}")

    # OETS: Run a study cycle during exploration downtime
    perception = systems.get('perception')
    if perception and perception.oets:
        if verbose:
            print()
            print("  [EXPLORE] Running OETS study cycle during downtime...")
        study_result = perception.oets.run_study_cycle()
        if verbose:
            researched = study_result.get('researched', 0)
            if researched > 0:
                for r in study_result.get('results', []):
                    print(f"          Studied: {r['word']} (defs={r.get('definitions', 0)}, "
                          f"rels={r.get('relations_added', 0)})")
            else:
                print("          (No research targets at this time)")

    if verbose:
        learned = aurora.gateway.simulation.session.learner.what_have_i_learned()
        print()
        if learned:
            print(f"  [EXPLORE] Aurora's insights:")
            for l in learned[:5]:
                print(f"          * {l}")
        print()

    # Close the discovery feedback loop: exploration results become memory
    # and lineage inputs instead of staying as a transient printout.
    try:
        study_result = locals().get("study_result", {}) or {}
        study_rows = list(study_result.get("results", []) or [])
        working_memory = systems.get("working_memory")
        conversation_memory = systems.get("conversation_memory")
        lineage_journal = systems.get("lineage_emergence_journal")
        understanding_contract = systems.get("understanding_contract")
        if study_rows:
            for row in study_rows[:8]:
                if not isinstance(row, dict):
                    continue
                word = str(row.get("word", "") or "").strip()
                defs = int(row.get("definitions", 0) or 0)
                rels = int(row.get("relations_added", 0) or 0)
                fact = f"Exploration studied {word or 'a concept'} ({defs} definitions, {rels} relations added)."
                if conversation_memory is not None and hasattr(conversation_memory, "learn_fact"):
                    try:
                        conversation_memory.learn_fact(
                            fact,
                            source="explore_study_cycle",
                            confidence=0.86,
                        )
                    except Exception as _aurora_boundary_exc:
                        _aurora_record_exception_from_locals(
                            locals(),
                            module=__name__,
                            operation="exception_handler:aurora.py:22478",
                            exc=_aurora_boundary_exc,
                            context={"function": "explore", "handler_line": 22478, "source_file": "aurora.py"},
                        )
                        pass
                if working_memory is not None and hasattr(working_memory, "note_user_facts"):
                    try:
                        working_memory.note_user_facts(fact)
                    except Exception as _aurora_boundary_exc:
                        _aurora_record_exception_from_locals(
                            locals(),
                            module=__name__,
                            operation="exception_handler:aurora.py:22483",
                            exc=_aurora_boundary_exc,
                            context={"function": "explore", "handler_line": 22483, "source_file": "aurora.py"},
                        )
                        pass
                if working_memory is not None and hasattr(working_memory, "_register_semantic_frame"):
                    try:
                        working_memory._register_semantic_frame({
                            "kind": "explore_study_cycle",
                            "anchor": word or "study_cycle",
                            "summary": fact,
                            "source": "explore_study_cycle",
                            "turn": int(getattr(working_memory, "turn_count", 0) or 0),
                            "confidence": 0.84,
                        })
                    except Exception as _aurora_boundary_exc:
                        _aurora_record_exception_from_locals(
                            locals(),
                            module=__name__,
                            operation="exception_handler:aurora.py:22495",
                            exc=_aurora_boundary_exc,
                            context={"function": "explore", "handler_line": 22495, "source_file": "aurora.py"},
                        )
                        pass
                if understanding_contract is not None and hasattr(understanding_contract, "ingest_observation"):
                    try:
                        understanding_contract.ingest_observation(
                            systems,
                            fact,
                            understood={
                                "topic": "explore_study_cycle",
                                "entities": [word] if word else [],
                                "source": "explore_study_cycle",
                            },
                            turn_tick=int(getattr(working_memory, "turn_count", 0) or 0) if working_memory is not None else 0,
                            source="explore_study_cycle",
                            session_id=str(systems.get("_session_id", "") or ""),
                        )
                    except Exception as _aurora_boundary_exc:
                        _aurora_record_exception_from_locals(
                            locals(),
                            module=__name__,
                            operation="exception_handler:aurora.py:22511",
                            exc=_aurora_boundary_exc,
                            context={"function": "explore", "handler_line": 22511, "source_file": "aurora.py"},
                        )
                        pass
            if lineage_journal is not None and hasattr(lineage_journal, "record_event"):
                try:
                    lineage_journal.record_event({
                        "timestamp": time.time(),
                        "source": "explore_study_cycle",
                        "kind": "discovery_cycle",
                        "id": f"study:{int(time.time())}",
                        "axis": "T",
                        "summary": f"Exploration study cycle integrated {len(study_rows)} result(s) into memory.",
                    })
                except Exception as _aurora_boundary_exc:
                    _aurora_record_exception_from_locals(
                        locals(),
                        module=__name__,
                        operation="exception_handler:aurora.py:22523",
                        exc=_aurora_boundary_exc,
                        context={"function": "explore", "handler_line": 22523, "source_file": "aurora.py"},
                    )
                    pass
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:22525",
            exc=_aurora_boundary_exc,
            context={"function": "explore", "handler_line": 22525, "source_file": "aurora.py"},
        )
        pass

    # Save after exploration and study
    _full_save(systems, verbose=verbose)


