def aurora_trade_blows(
    systems: Dict[str, Any],
    first_clue: str = "",
    verbose: bool = True,
) -> None:
    """
    Interactive reasoning game session — wraps GameStateMachine in a
    blocking REPL loop. Canonical game logic lives in aurora_reasoning_games.
    """
    from aurora_reasoning_games import GameStateMachine

    def _generate(prompt: str) -> str:
        try:
            result = process_external_user_turn(
                systems, prompt,
                source_label="game:internal",
                session_id="trade_blows",
                auto_search_enabled=False,
                record_exchange=False,
                update_interactive_state=False,
                track_evolutionary_trace=True,
                run_periodic_maintenance=False,
                mode_name="BOUNDED",
            )
            resp_a = result.get("resp_A")
            return str(getattr(resp_a, "content", "") or "")
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:22579",
                exc=_aurora_boundary_exc,
                context={"function": "_generate", "handler_line": 22579, "source_file": "aurora.py"},
            )
            return ""

    gm = GameStateMachine(systems, generate_fn=_generate)
    print(f"\n  {gm.start()}")

    # If started from "I'm thinking of something X", feed first clue immediately
    if first_clue:
        resp = gm.process(first_clue)
        if resp:
            print(f"  Aurora: {resp}")

    while not gm.is_done:
        try:
            user_inp = input("\n  You: ").strip()
        except (EOFError, KeyboardInterrupt) as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:22594",
                exc=_aurora_boundary_exc,
                context={"function": "aurora_trade_blows", "handler_line": 22594, "source_file": "aurora.py"},
            )
            break
        if not user_inp:
            continue
        resp = gm.process(user_inp)
        if resp:
            print(f"\n  Aurora: {resp}")


