def _capture_hardware_voice_state(integration: Any) -> Dict[str, Any]:
    """Persist the shared TTS voice so daemon and REPL stay aligned."""
    hardware = getattr(integration, 'hardware', None) if integration else None
    voice = getattr(hardware, 'voice', None) if hardware else None
    if not voice:
        return {}

    voice_id = str(getattr(voice, 'voice_name', '') or '').strip()
    voice_state: Dict[str, Any] = {}
    if voice_id:
        voice_state['voice_id'] = voice_id

    if hasattr(voice, 'list_voices'):
        try:
            presets = dict(voice.list_voices() or {})
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:25248",
                exc=_aurora_boundary_exc,
                context={"function": "_capture_hardware_voice_state", "handler_line": 25248, "source_file": "aurora.py"},
            )
            presets = {}
        if voice_id:
            for preset_name, preset_id in presets.items():
                if preset_id == voice_id:
                    voice_state['voice_preset'] = preset_name
                    break

    if hasattr(voice, 'get_current_voice'):
        try:
            voice_state['voice_label'] = str(voice.get_current_voice() or '')
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:25259",
                exc=_aurora_boundary_exc,
                context={"function": "_capture_hardware_voice_state", "handler_line": 25259, "source_file": "aurora.py"},
            )
            pass

    return voice_state


def _restore_hardware_voice_state(integration: Any, voice_state: Any) -> bool:
    """Restore the shared TTS voice from saved sensory state."""
    if not integration or not isinstance(voice_state, dict):
        return False

    hardware = getattr(integration, 'hardware', None)
    voice = getattr(hardware, 'voice', None) if hardware else None
    if not voice or not hasattr(voice, 'set_voice'):
        return False

    candidate = str(
        voice_state.get('voice_preset')
        or voice_state.get('voice_id')
        or ''
    ).strip()
    if not candidate:
        return False

    try:
        return bool(voice.set_voice(candidate))
    except Exception as _aurora_boundary_exc:
        _aurora_record_exception_from_locals(
            locals(),
            module=__name__,
            operation="exception_handler:aurora.py:25285",
            exc=_aurora_boundary_exc,
            context={"function": "_restore_hardware_voice_state", "handler_line": 25285, "source_file": "aurora.py"},
        )
        return False

def _load_learned_skill_state(systems: Dict[str, Any], verbose: bool = True) -> bool:
    """Restore learned cross-modal skills (sensory integration mappings)."""
    state_dir = systems.get('state_dir', 'aurora_state')
    skill_file = Path(state_dir) / 'aurora_learned_skills.json'
    integration = systems.get('sensory_integration')
    if not integration or not skill_file.exists():
        return False

    try:
        data = json.loads(skill_file.read_text())
        visual = data.get('visual_mapper', {})
        audio = data.get('audio_mapper', {})

        integration.visual_mapper.learned_associations = dict(
            visual.get('learned_associations', {})
        )
        integration.visual_mapper.description_history = list(
            visual.get('description_history', [])
        )[-200:]

        integration.audio_mapper.learned_voices = dict(
            audio.get('learned_voices', {})
        )
        integration.audio_mapper.transcription_history = list(
            audio.get('transcription_history', [])
        )[-300:]
        _restore_hardware_voice_state(
            integration,
            data.get('hardware_voice', {}),
        )

        if verbose:
            print("  [SKILLS] Restored learned sensory mappings")
        return True
    except Exception as e:
        if verbose:
            print(f"  [SKILLS] Restore failed: {e}")
        return False


def _save_learned_skill_state(systems: Dict[str, Any], verbose: bool = True) -> bool:
    """Persist learned cross-modal skills into the same state directory."""
    state_dir = systems.get('state_dir', 'aurora_state')
    skill_file = Path(state_dir) / 'aurora_learned_skills.json'
    integration = systems.get('sensory_integration')
    if not integration:
        return False

    try:
        skill_file.parent.mkdir(parents=True, exist_ok=True)
        data = {
            'version': '1.0',
            'timestamp': time.time(),
            'visual_mapper': {
                'learned_associations': integration.visual_mapper.learned_associations,
                'description_history': integration.visual_mapper.description_history[-200:],
            },
            'audio_mapper': {
                'learned_voices': integration.audio_mapper.learned_voices,
                'transcription_history': integration.audio_mapper.transcription_history[-300:],
            },
            'hardware_voice': _capture_hardware_voice_state(integration),
        }
        skill_file.write_text(json.dumps(data, indent=1, default=str))
        if verbose:
            print("  [SAVE] Saved: learned_skills")
        return True
    except Exception as e:
        if verbose:
            print(f"  [SAVE] Learned skill save failed: {e}")
        return False


def save_sensory_skill_state(systems: Dict[str, Any], verbose: bool = True) -> bool:
    """Public bridge for daemon/voice paths that need the same sensory save."""
    return _save_learned_skill_state(systems, verbose=verbose)


