def _safe_join_parts(parts: Any) -> str:
    if parts is None:
        return ""
    if isinstance(parts, str):
        return parts
    if isinstance(parts, list):
        out = []
        for p in parts:
            if isinstance(p, str):
                out.append(p)
            elif isinstance(p, dict):
                # Sometimes exports contain rich objects; try common fields
                if 'text' in p and isinstance(p['text'], str):
                    out.append(p['text'])
                elif 'content' in p and isinstance(p['content'], str):
                    out.append(p['content'])
        return "\n".join([s for s in out if s])
    return str(parts)


def _extract_message_text(message_obj: Dict[str, Any]) -> str:
    """
    OpenAI export nodes typically look like:
      message: {
        author: {role: "user"|"assistant"|"system"}
        content: {content_type: "text", parts: [...]}
      }
    """
    if not message_obj:
        return ""

    content = message_obj.get("content") or {}
    if isinstance(content, dict):
        parts = content.get("parts")
        txt = _safe_join_parts(parts).strip()
        if txt:
            return txt

        # Fallback: sometimes "text" exists directly
        txt2 = content.get("text")
        if isinstance(txt2, str):
            return txt2.strip()

    # Fallback: raw string
    if isinstance(content, str):
        return content.strip()

    return ""


def _extract_role(message_obj: Dict[str, Any]) -> str:
    if not message_obj:
        return "unknown"
    author = message_obj.get("author") or {}
    role = author.get("role") or "unknown"
    return role


def _reconstruct_linear_thread(mapping: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    The OpenAI export uses a mapping graph.
    We reconstruct a linear chain by:
      - finding roots (parent is None)
      - walking children depth-first preferring the longest path
    This isn't perfect for branching chats, but works well enough.
    """
    if not mapping:
        return []

    # Find roots
    roots = []
    for node_id, node in mapping.items():
        if not isinstance(node, dict):
            continue
        if node.get("parent") is None:
            roots.append(node_id)

    if not roots:
        # fallback: arbitrary start
        roots = [next(iter(mapping.keys()))]

    def walk_from(node_id: str) -> List[str]:
        path = [node_id]
        current = node_id
        visited = set([node_id])

        while True:
            node = mapping.get(current) or {}
            children = node.get("children") or []
            if not children:
                break

            # Prefer first unseen child; exports usually store chronological continuation first
            next_child = None
            for c in children:
                if c not in visited:
                    next_child = c
                    break
            if next_child is None:
                break

            visited.add(next_child)
            path.append(next_child)
            current = next_child

        return path

    # Choose the longest root path (best approximation of the main conversation)
    best_path = []
    for r in roots:
        p = walk_from(r)
        if len(p) > len(best_path):
            best_path = p

    nodes = []
    for nid in best_path:
        node = mapping.get(nid)
        if isinstance(node, dict):
            nodes.append(node)
    return nodes


def _extract_messages_from_conversation(conv_obj: Dict[str, Any]) -> List[Tuple[str, str]]:
    """
    Returns a list of (role, text) in chronological order.
    Filters out empty/system/tool messages.
    """
    mapping = conv_obj.get("mapping") or {}
    if not isinstance(mapping, dict):
        return []

    nodes = _reconstruct_linear_thread(mapping)

    extracted: List[Tuple[str, str]] = []
    for node in nodes:
        msg = node.get("message")
        if not msg:
            continue

        role = _extract_role(msg)
        if role not in ("user", "assistant"):
            continue

        text = _extract_message_text(msg)
        if not text:
            continue

        extracted.append((role, text))

    return extracted


def _load_openai_conversations(path: str) -> List[Dict[str, Any]]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Most exports are a list of conversations
    if isinstance(data, list):
        return [d for d in data if isinstance(d, dict)]

    # Some variants wrap in an object
    if isinstance(data, dict):
        if "conversations" in data and isinstance(data["conversations"], list):
            return [d for d in data["conversations"] if isinstance(d, dict)]
        if "data" in data and isinstance(data["data"], list):
            return [d for d in data["data"] if isinstance(d, dict)]

    return []


_CORPUS_PRESSURE_STOPWORDS = {
    'the', 'and', 'for', 'with', 'that', 'this', 'from', 'have', 'what',
    'when', 'where', 'which', 'would', 'could', 'should', 'there', 'their',
    'about', 'your', 'them', 'they', 'into', 'than', 'then', 'because',
    'while', 'were', 'been', 'being', 'does', 'dont', 'did', 'just', 'also',
    'very', 'much', 'more', 'some', 'like', 'want', 'need', 'know', 'think',
    'only', 'really', 'still', 'make', 'made', 'through', 'here', 'them',
}


def _corpus_pressure_token_set(text: str):
    return {
        token for token in re.findall(r"[a-z0-9']+", (text or "").lower())
        if len(token) > 2 and token not in _CORPUS_PRESSURE_STOPWORDS
    }


def _corpus_overlap(a: str, b: str) -> float:
    a_tokens = _corpus_pressure_token_set(a)
    b_tokens = _corpus_pressure_token_set(b)
    if not a_tokens or not b_tokens:
        return 0.0
    return len(a_tokens & b_tokens) / float(min(len(a_tokens), len(b_tokens)))


def _classify_corpus_response_pressure_kind(
    prompt_text: str,
    aurora_text: str,
    truth_text: str,
) -> str:
    prompt_low = str(prompt_text or '').lower()
    aurora_low = str(aurora_text or '').lower()
    truth_low = str(truth_text or '').lower()
    aurora_padded = f" {aurora_low} "
    truth_padded = f" {truth_low} "
    vague_followup = (
        _looks_like_question(prompt_text)
        and (
            len((prompt_text or '').split()) <= 8
            or any(
                token in prompt_low.split()
                for token in ('it', 'that', 'this', 'they', 'them', 'he', 'she', 'those')
            )
        )
    )
    if vague_followup:
        return 'followup'

    uncertainty_markers = ('maybe', 'perhaps', 'might', 'not sure', 'unclear', 'unsure')
    if any(marker in prompt_low or marker in aurora_low or marker in truth_low for marker in uncertainty_markers):
        return 'uncertainty'

    aurora_negated = any(marker in aurora_padded for marker in (" not ", "n't", ' never ', ' no '))
    truth_negated = any(marker in truth_padded for marker in (" not ", "n't", ' never ', ' no '))
    if aurora_negated != truth_negated and _corpus_overlap(aurora_text, truth_text) >= 0.18:
        return 'repair'

    if _corpus_overlap(prompt_text, truth_text) < 0.10 and _corpus_overlap(aurora_text, truth_text) < 0.15:
        return 'repair'

    return 'reply'


def _record_corpus_response_pressure(
    systems: Dict[str, Any],
    prompt_text: str,
    aurora_text: str,
    truth_text: str,
    phase: str,
) -> Dict[str, Any]:
    from aurora_internal.aurora_response_pressure_tuner import ResponsePressureTuner

    if not aurora_text:
        return {}

    tuner = systems.get('_corpus_response_pressure_tuner')
    if tuner is None:
        tuner = ResponsePressureTuner(namespace='corpus.ingestion')
        systems['_corpus_response_pressure_tuner'] = tuner

    truth_alignment = _corpus_overlap(aurora_text, truth_text)
    prompt_grounding = _corpus_overlap(aurora_text, prompt_text)
    prompt_truth_overlap = _corpus_overlap(prompt_text, truth_text)
    aurora_tokens = _corpus_pressure_token_set(aurora_text)
    truth_tokens = _corpus_pressure_token_set(truth_text)
    prompt_tokens = _corpus_pressure_token_set(prompt_text)
    prompt_words = set(re.findall(r"[a-z0-9']+", (prompt_text or '').lower()))

    truth_len = max(1, len(truth_tokens))
    length_ratio = len(aurora_tokens) / float(truth_len)
    length_fit = max(0.0, 1.0 - min(abs(length_ratio - 1.0), 1.0))
    prompt_is_question = _looks_like_question(prompt_text)
    callback_like = (
        prompt_is_question
        and (
            len(prompt_tokens) <= 6
            or any(token in prompt_words for token in ('that', 'this', 'those', 'they', 'it'))
        )
    )

    kind = _classify_corpus_response_pressure_kind(prompt_text, aurora_text, truth_text)
    difficulty = 0.0
    if prompt_is_question:
        difficulty += 0.08
    if callback_like:
        difficulty += 0.14
    if prompt_truth_overlap < 0.18:
        difficulty += 0.12
    if len(prompt_tokens) <= 4:
        difficulty += 0.08
    if len(truth_tokens) >= 18:
        difficulty += 0.05
    counter_pressure = max(0.0, min(0.42, difficulty))

    signal = (
        0.24
        + 0.42 * truth_alignment
        + 0.18 * prompt_grounding
        + 0.10 * length_fit
        + (0.06 if prompt_is_question else 0.0)
    )
    if kind == 'followup' and prompt_grounding > 0.30:
        signal += 0.04
    if kind == 'repair' and truth_alignment < 0.22:
        signal -= 0.06
    signal = max(0.0, min(1.0, signal))
    threshold = max(0.48, min(0.88, 0.58 + counter_pressure))

    tuner.evaluate(
        kind=kind,
        content=str(aurora_text or '')[:240],
        signal=signal,
        threshold=threshold,
        counter_pressure=counter_pressure,
        factors={
            'truth_alignment': round(truth_alignment, 4),
            'prompt_grounding': round(prompt_grounding, 4),
            'prompt_truth_overlap': round(prompt_truth_overlap, 4),
            'length_fit': round(length_fit, 4),
            'callback_like': 1.0 if callback_like else 0.0,
        },
        context={
            'phase': phase,
            'prompt_is_question': prompt_is_question,
            'prompt_tokens': len(prompt_tokens),
            'truth_tokens': len(truth_tokens),
        },
    )
    quasiarch = systems.get('quasiarch_observer')
    if quasiarch is not None and hasattr(quasiarch, 'record_corpus_response'):
        try:
            quasiarch.record_corpus_response(
                prompt_text=prompt_text,
                aurora_text=aurora_text,
                truth_text=truth_text,
                phase=phase,
                kind=kind,
                signal=signal,
                threshold=threshold,
                counter_pressure=counter_pressure,
                prompt_grounding=prompt_grounding,
                truth_alignment=truth_alignment,
            )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:27741",
                exc=_aurora_boundary_exc,
                context={"function": "_record_corpus_response_pressure", "handler_line": 27741, "source_file": "aurora.py"},
            )
            pass
    return {
        'kind': kind,
        'signal': round(signal, 4),
        'threshold': round(threshold, 4),
        'truth_alignment': round(truth_alignment, 4),
        'prompt_grounding': round(prompt_grounding, 4),
        'length_fit': round(length_fit, 4),
        'counter_pressure': round(counter_pressure, 4),
        'phase': str(phase or ''),
    }


def run_corpus_ingestion(
    systems: Dict[str, Any],
    corpus_path: str,
    train_every: int = 200,
    save_every: int = 1000,
    passes: str = "triple",
    burst_epochs: int = 20,
    burst_episodes: int = 8,
    burst_turns: int = 5,
    burst_study_cycles: int = 0,
    verbose: bool = True,
):
    """
    Ingest OpenAI export conversations.json into Aurora using multiple passes.

    PASSES:
      - observer: Aurora witnesses all messages, no response generation.
      - responder: Aurora responds to user messages, then witnesses assistant truth.
      - reverse: Aurora responds to assistant messages, then witnesses user truth.
      - triple: observer -> responder -> reverse
    """
    aurora = systems["aurora"]
    StreamType = systems["StreamType"]
    ExistenceMode = systems["ExistenceMode"]
    conversation_memory = systems.get("conversation_memory")
    if systems.get('_corpus_response_pressure_tuner') is None:
        from aurora_internal.aurora_response_pressure_tuner import ResponsePressureTuner
        systems['_corpus_response_pressure_tuner'] = ResponsePressureTuner(
            namespace='corpus.ingestion'
        )
    from aurora_internal.aurora_learning_pipeline import LearningQualityGate
    _corpus_quality_gate = LearningQualityGate()

    corpus_path = os.path.expanduser(corpus_path)

    if not os.path.exists(corpus_path):
        raise FileNotFoundError(f"Corpus file not found: {corpus_path}")

    if verbose:
        print()
        print("=" * 60)
        print("  [CORPUS] Ingestion starting")
        print(f"  [CORPUS] File: {corpus_path}")
        print(f"  [CORPUS] train_every={train_every} messages")
        print(f"  [CORPUS] burst=epochs:{burst_epochs} episodes:{burst_episodes} turns:{burst_turns} study:{burst_study_cycles}")
        print(f"  [CORPUS] save_every={save_every} messages")
        print(f"  [CORPUS] passes={passes}")
        print("=" * 60)
        print()

    conversations = _load_openai_conversations(corpus_path)
    if verbose:
        print(f"  [CORPUS] Loaded {len(conversations)} conversations")

    # Flatten into one big chronological stream (conversation order in export)
    stream: List[Tuple[str, str]] = []
    for conv in conversations:
        msgs = _extract_messages_from_conversation(conv)
        if msgs:
            stream.extend(msgs)

    if verbose:
        print(f"  [CORPUS] Extracted {len(stream)} total messages (user+assistant)")

    if not stream:
        if verbose:
            print("  [CORPUS] No usable messages found. Aborting.")
        return

    def _record_corpus_observation(role: str, content: str, quality: Dict[str, Any], source: str) -> None:
        ledger = systems.setdefault('_corpus_observation_ledger', [])
        ledger.append({
            'role': str(role or ''),
            'source': str(source or ''),
            'content': str(content or '')[:320],
            'quality': dict(quality or {}),
            'timestamp': time.time(),
        })
        systems['_corpus_observation_ledger'] = ledger[-500:]
        if quality.get('missing_context'):
            gaps = systems.setdefault('_corpus_context_gaps', [])
            gaps.append({
                'role': str(role or ''),
                'content': str(content or '')[:240],
                'markers': list(quality.get('missing_context') or []),
                'timestamp': time.time(),
            })
            systems['_corpus_context_gaps'] = gaps[-100:]

    def _persist_corpus_observations() -> None:
        try:
            from aurora_persistence_utils import atomic_write_json
            atomic_write_json(
                Path(str(systems.get('state_dir') or 'aurora_state')) / 'corpus_observations.json',
                {
                    'schema_version': 1,
                    'observations': list(systems.get('_corpus_observation_ledger', []) or [])[-500:],
                    'context_gaps': list(systems.get('_corpus_context_gaps', []) or [])[-100:],
                    'quality_status': _corpus_quality_gate.status(),
                },
                indent=2,
                default=str,
            )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:_persist_corpus_observations",
                exc=_aurora_boundary_exc,
                context={"function": "_persist_corpus_observations", "source_file": "aurora.py"},
            )
            pass

    def witness(role: str, content: str, source: str):
        # Keep stale/thin corpus material as an observation, not as new
        # knowledge.  This gate is intentionally separate from response
        # outcome classification: a short "yes" can validate a response, but
        # it should not become a corpus fact by itself.
        quality = _corpus_quality_gate.observe(content, role=role)
        _record_corpus_observation(role, content, quality, source)
        systems['_last_corpus_quality'] = dict(quality)
        if not quality.get('eligible_for_learning'):
            return None

        # Feed into Aurora as knowledge feed (bounded so it can form meaning)
        response = aurora.gateway.receive(
            content=f"[{role.upper()}] {content}",
            stream_type=StreamType.KNOWLEDGE_FEED,
            source=source,
            mode=ExistenceMode.BOUNDED,
        )
        if conversation_memory:
            try:
                conversation_memory.learn_fact(
                    fact=f"[{role}] {content[:280]}",
                    source=source,
                    confidence=0.55,
                )
            except Exception as _aurora_boundary_exc:
                _aurora_record_exception_from_locals(
                    locals(),
                    module=__name__,
                    operation="exception_handler:aurora.py:27827",
                    exc=_aurora_boundary_exc,
                    context={"function": "witness", "handler_line": 27827, "source_file": "aurora.py"},
                )
                pass
        return response

    def _resolve_corpus_response_learning(pressure: Dict[str, Any], phase: str) -> None:
        """Use the corpus truth pair as explicit, bounded receiver evidence."""
        if not pressure or 'signal' not in pressure:
            return
        dt = systems.get('dream_trainer')
        if dt is None or not hasattr(dt, 'resolve_pipeline_learning'):
            return
        response_id = str(
            systems.get('_last_staged_pipeline_response_id')
            or ''
        ).strip()
        if not response_id:
            return
        signal = float(pressure.get('signal', 0.0) or 0.0)
        threshold = float(pressure.get('threshold', 1.0) or 1.0)
        kind = 'positive' if signal >= threshold else 'negative'
        try:
            dt.resolve_pipeline_learning(
                response_id,
                outcome_kind=kind,
                evidence_id=f'corpus:{phase}:{response_id}',
                score=signal,
                observed_effect='corpus_truth_alignment',
                turn_tick=int(systems.get('_corpus_learning_tick', 0) or 0),
                systems=systems,
            )
        except Exception as _aurora_boundary_exc:
            _aurora_record_exception_from_locals(
                locals(),
                module=__name__,
                operation="exception_handler:aurora.py:_resolve_corpus_response_learning",
                exc=_aurora_boundary_exc,
                context={"function": "_resolve_corpus_response_learning", "source_file": "aurora.py"},
            )
            pass

    def generate_reply(prompt_text: str, source: str):
        if not prompt_text or len(prompt_text.split()) < 3:
            return None
        result = process_external_user_turn(
            systems,
            prompt_text,
            source_label=f'corpus_ingestion:{source}',
            session_id='corpus_ingestion',
            auto_search_enabled=True,
            record_exchange=True,
            update_interactive_state=False,
            track_evolutionary_trace=True,
            run_periodic_maintenance=False,
            mode_name='AGENTIC',
        )
        return result.get('resp_A')

    def maybe_train(counter: int):
        if train_every > 0 and counter % train_every == 0:
            if verbose:
                print(f"\n  [CORPUS] Training burst at message {counter:,}")
            train(
                systems,
                epochs=burst_epochs,
                episodes_per_epoch=burst_episodes,
                turns_per_episode=burst_turns,
                verbose=verbose,
                phase_prefix='corpus_burst',
            )
            if burst_study_cycles > 0:
                if verbose:
                    print(f"  [CORPUS] Study burst after training ({burst_study_cycles} cycles)")
                study(systems, cycles=burst_study_cycles, verbose=verbose)

    def maybe_save(counter: int):
        if save_every > 0 and counter % save_every == 0:
            if verbose:
                print(f"\n  [CORPUS] Saving state at message {counter:,}")
            _full_save(systems, verbose=verbose)

    def pass_observer():
        if verbose:
            print("\n  [CORPUS] PASS 1  OBSERVER (witness only)\n")

        counter = 0
        for role, content in stream:
            counter += 1
            witness(role, content, source="corpus_observer")
            maybe_train(counter)
            maybe_save(counter)

        if verbose:
            print(f"\n  [CORPUS] Observer pass complete. Messages processed: {counter:,}")

    def pass_responder():
        if verbose:
            print("\n  [CORPUS] PASS 2  RESPONDER (Aurora replies to USER)\n")

        counter = 0
        i = 0
        while i < len(stream) - 1:
            role, content = stream[i]
            next_role, next_content = stream[i + 1]

            # We only respond when the user speaks and assistant follows
            if role == "user" and next_role == "assistant":
                counter += 1
                # Prompt Aurora to respond
                resp = generate_reply(content, source="corpus_responder")
                _pressure = _record_corpus_response_pressure(
                    systems,
                    prompt_text=content,
                    aurora_text=getattr(resp, 'content', ''),
                    truth_text=next_content,
                    phase='corpus_responder',
                )
                systems['_corpus_learning_tick'] = int(
                    systems.get('_corpus_learning_tick', 0) or 0
                ) + 1
                _resolve_corpus_response_learning(_pressure, 'responder')
                # Then show the "true" assistant reply as ground-truth continuation
                witness("assistant_truth", next_content, source="corpus_responder_truth")

                if verbose and counter % 50 == 0:
                    snippet = (resp.content or "")[:120].replace("\n", " ")
                    print(f"  [CORPUS] responder step {counter:,} | aurora='{snippet}...'")

                maybe_train(counter)
                maybe_save(counter)
                i += 2
            else:
                i += 1

        if verbose:
            print(f"\n  [CORPUS] Responder pass complete. Pairs processed: {counter:,}")

    def pass_reverse():
        if verbose:
            print("\n  [CORPUS] PASS 3  REVERSE (Aurora replies to ASSISTANT)\n")

        counter = 0
        i = 0
        while i < len(stream) - 1:
            role, content = stream[i]
            next_role, next_content = stream[i + 1]

            # Now we respond when assistant speaks and user follows
            if role == "assistant" and next_role == "user":
                counter += 1
                resp = generate_reply(content, source="corpus_reverse")
                _pressure = _record_corpus_response_pressure(
                    systems,
                    prompt_text=content,
                    aurora_text=getattr(resp, 'content', ''),
                    truth_text=next_content,
                    phase='corpus_reverse',
                )
                systems['_corpus_learning_tick'] = int(
                    systems.get('_corpus_learning_tick', 0) or 0
                ) + 1
                _resolve_corpus_response_learning(_pressure, 'reverse')
                witness("user_truth", next_content, source="corpus_reverse_truth")

                if verbose and counter % 50 == 0:
                    snippet = (resp.content or "")[:120].replace("\n", " ")
                    print(f"  [CORPUS] reverse step {counter:,} | aurora='{snippet}...'")

                maybe_train(counter)
                maybe_save(counter)
                i += 2
            else:
                i += 1

        if verbose:
            print(f"\n  [CORPUS] Reverse pass complete. Pairs processed: {counter:,}")

    # Run passes
    passes = (passes or "triple").strip().lower()

    if passes == "observer":
        pass_observer()
    elif passes == "responder":
        pass_responder()
    elif passes == "reverse":
        pass_reverse()
    elif passes in ("both", "double"):
        pass_observer()
        pass_responder()
    else:
        # default triple
        pass_observer()
        pass_responder()
        pass_reverse()

    if verbose:
        print("\n  [CORPUS] Ingestion complete. Final save.")
    _persist_corpus_observations()
    _full_save(systems, verbose=verbose)
def main():
    parser = argparse.ArgumentParser(
        description="Aurora  Consciousness Architecture Runner",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python3 aurora.py                    # Boot and chat
  python3 aurora.py --train 50         # Train 50 epochs then chat
  python3 aurora.py --train 100 --no-chat   # Train only, no chat
  python3 aurora.py --explore 20       # Autonomous exploration
  python3 aurora.py --feed https://example.com  # Feed a URL
  python3 aurora.py --text "The sky is blue"    # Feed raw text
  python3 aurora.py --status           # Show system status
        """)

    parser.add_argument('--train', type=int, default=0,
                        help='Run N training epochs before chat')
    parser.add_argument('--train-episodes', type=int, default=8,
                        help='Episodes per training epoch (default: 8)')
    parser.add_argument('--train-turns', type=int, default=5,
                        help='Turns per training episode (default: 5)')
    parser.add_argument('--explore', type=int, default=0,
                        help='Run N autonomous exploration cycles')
    parser.add_argument('--study', type=int, default=0,
                        help='Run N autonomous study cycles (OETS research)')
    parser.add_argument('--feed', type=str, default=None,
                        help='Feed a URL to Aurora')
    parser.add_argument('--text', type=str, default=None,
                        help='Feed raw text to Aurora')
    parser.add_argument('--corpus', type=str, default=None,
                        help='Ingest an OpenAI conversations.json corpus into Aurora')
    parser.add_argument('--corpus-passes', type=str, default='triple',
                        help='observer|responder|reverse|double|triple (default: triple)')
    parser.add_argument('--corpus-train-every', type=int, default=200,
                        help='Run a training burst every N corpus messages (default: 200)')
    parser.add_argument('--corpus-burst-epochs', type=int, default=20,
                        help='Epochs to run per corpus training burst (default: 20)')
    parser.add_argument('--corpus-burst-episodes', type=int, default=8,
                        help='Episodes per epoch for corpus training burst (default: 8)')
    parser.add_argument('--corpus-burst-turns', type=int, default=5,
                        help='Turns per episode for corpus training burst (default: 5)')
    parser.add_argument('--corpus-burst-study', type=int, default=0,
                        help='Study cycles to run after each corpus training burst (default: 0)')
    parser.add_argument('--corpus-save-every', type=int, default=1000,
                        help='Save Aurora state every N corpus messages (default: 1000)')
    parser.add_argument('--status', action='store_true',
                        help='Show system status and exit')
    parser.add_argument('--no-chat', action='store_true',
                        help='Skip interactive chat')
    parser.add_argument('--state-dir', type=str, default='aurora_state',
                        help='Directory for state persistence')
    parser.add_argument('--quiet', action='store_true',
                        help='Minimal output')

    args = parser.parse_args()
    verbose = not args.quiet

    # Boot
    systems = boot_aurora(state_dir=args.state_dir, verbose=verbose)

    # Training
    if args.train > 0:
        train(
            systems,
            epochs=args.train,
            episodes_per_epoch=args.train_episodes,
            turns_per_episode=args.train_turns,
            verbose=verbose,
        )

    # Feed URL
    if args.feed:
        fetch_and_feed(systems, args.feed, verbose=verbose)

    # Feed text
    if args.text:
        feed_text(systems, args.text, verbose=verbose)


    # Corpus ingestion (OpenAI export conversations.json)
    if args.corpus:
        run_corpus_ingestion(
            systems,
            corpus_path=args.corpus,
            train_every=args.corpus_train_every,
            save_every=args.corpus_save_every,
            passes=args.corpus_passes,
            burst_epochs=args.corpus_burst_epochs,
            burst_episodes=args.corpus_burst_episodes,
            burst_turns=args.corpus_burst_turns,
            burst_study_cycles=args.corpus_burst_study,
            verbose=verbose,
        )
    gate_on, gate_msg = _get_autonomous_access_state()

    # Explore
    if args.explore > 0:
        if gate_on:
            explore(systems, cycles=args.explore, verbose=verbose)
        else:
            print(f"  [AUTONOMY] Explore blocked: autonomous access lease {gate_msg}.")

    # Study (OETS autonomous research)
    if args.study > 0:
        if gate_on:
            study(systems, cycles=args.study, verbose=verbose)
        else:
            print(f"  [AUTONOMY] Study blocked: autonomous access lease {gate_msg}.")

    # Status
    if args.status:
        show_status(systems)

    # Chat
    if not args.no_chat and not args.status:
        chat(systems)


if __name__ == '__main__':
    main()

